head.script:
//
/* تشغيل دالة عند أول تفاعل */
window.onFirstInteraction=function(fn,maxWait){
  var done=false;
  function go(){ if(done) return; done=true; fn(); }
  ['scroll','touchstart','pointerdown','keydown','mousemove','click'].forEach(function(e){
    addEventListener(e,go,{passive:true,once:true});
  });
  setTimeout(go,Math.max(maxWait||0,25000));
};
/* الخطوط بعد تحميل الصفحة */
(function(){
  function add(h){var l=document.createElement('link');l.rel='stylesheet';l.href=h;document.head.appendChild(l)}
  function go(){
    add('https://fonts.googleapis.com/css2?family=Blaka&text=%D8%AF.%20%D9%85%D9%80%D8%A4%D9%85%D9%80%D9%86&display=swap');
  }
  if(document.readyState==='complete') go(); else addEventListener('load',go);
})();
/* سجل التحميل الكسول: كل ويدجت ثقيل بيتسجل هنا وبيشتغل أول ما الزائر يضغط على التاب بتاعه */
window.__lazyInit=window.__lazyInit||{};
/* فك حجب CSS الخاص ببلوجر وGoogle Fonts عن الرسم الأول */
(function(){
  try{
    var re=/widget_css_bundle|fonts\.googleapis\.com\/css2\?/;
    function fix(n){
      if(!n||n.tagName!=='LINK'||n.__nb||String(n.rel).toLowerCase()!=='stylesheet'||!re.test(n.href||'')) return;
      n.__nb=1;
      var on=function(){n.media='all'};
      n.media='print';
      n.addEventListener('load',on,{once:true});
      n.addEventListener('error',on,{once:true});
      setTimeout(on,2000);
    }
    var mo=new MutationObserver(function(ms){
      for(var i=0;i<ms.length;i++){
        var a=ms[i].addedNodes;
        for(var j=0;j<a.length;j++) fix(a[j]);
      }
    });
    mo.observe(document.head,{childList:true,subtree:true});
    addEventListener('load',function(){setTimeout(function(){mo.disconnect()},1500)});
  }catch(e){}
})();
/* صفحة البحث المخصصة: نخفي نتائج بلوجر الافتراضية فورًا لتفادي الوميض */
try{var __p=location.pathname,__s=location.search;if(__p==='/search'&&/[?&]q=/.test(__s)&&!/[?&]cs=0/.test(__s))document.documentElement.classList.add('cs-on')}catch(e){}
/* تأجيل طلب إحصائيات بلوجر (/b/stats) لحد ما الزائر يضغط زرار الإحصائيات */
(function(){
  try{
    var held=[],released=false,re=/\/b\/stats\b/;
    window.__releaseStats=function(){
      if(released) return; released=true;
      held.splice(0).forEach(function(f){try{f()}catch(e){}});
    };
    function isStats(n){return n&&n.tagName==='SCRIPT'&&re.test(n.src||'')}
    var ac=Node.prototype.appendChild, ib=Node.prototype.insertBefore;
    Node.prototype.appendChild=function(n){
      if(!released&&isStats(n)){var p=this;held.push(function(){ac.call(p,n)});return n}
      return ac.call(this,n)};
    Node.prototype.insertBefore=function(n,r){
      if(!released&&isStats(n)){var p=this;held.push(function(){ib.call(p,n,r)});return n}
      return ib.call(this,n,r)};
    var xo=XMLHttpRequest.prototype.open, xs=XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open=function(m,u){this.__u=String(u||'');return xo.apply(this,arguments)};
    XMLHttpRequest.prototype.send=function(){
      var x=this,a=arguments;
      if(!released&&re.test(x.__u||'')){held.push(function(){xs.apply(x,a)});return}
      return xs.apply(x,a)};
    var of=window.fetch;
    if(of) window.fetch=function(u,o){
      var url=typeof u==='string'?u:((u&&u.url)||'');
      if(!released&&re.test(url)){return new Promise(function(res,rej){held.push(function(){of.call(window,u,o).then(res,rej)})})}
      return of.apply(this,arguments)};
  }catch(e){}
})();
/* تأجيل سكريبتات الإعلانات وكونسنت جوجل وخطوطها لحد أول تفاعل من الزائر (بيتم اعتراض أي سكريبت/ستايل بيتضاف ديناميكيًا) */
(function(){
  try{
    var held=[],released=false,
        reS=/show_ads_impl|adsbygoogle|googlesyndication|\/pagead\/|fundingchoices|doubleclick\.net|googletagservices|google_top_exp/i,
        reL=/fonts\.googleapis\.com\/css2\?/i;
    function isAd(n){
      if(released||!n||n.nodeType!==1) return false;
      var t=n.tagName;
      if(t==='SCRIPT') return !!n.src&&reS.test(n.src);
      if(t==='LINK') return String(n.rel).toLowerCase()==='stylesheet'&&reL.test(n.href||'')&&(n.href||'').indexOf('Blaka')<0;
      return false;
    }
    window.__releaseAds=function(){
      if(released) return; released=true;
      held.splice(0).forEach(function(f){try{f()}catch(e){}});
    };
    var ac2=Node.prototype.appendChild, ib2=Node.prototype.insertBefore;
    Node.prototype.appendChild=function(n){
      if(isAd(n)){var p=this;held.push(function(){ac2.call(p,n)});return n}
      return ac2.call(this,n)};
    Node.prototype.insertBefore=function(n,r){
      if(isAd(n)){var p=this;held.push(function(){ib2.call(p,n,r)});return n}
      return ib2.call(this,n,r)};
    ['scroll','touchstart','pointerdown','keydown','mousemove','click'].forEach(function(e){
      addEventListener(e,window.__releaseAds,{passive:true,once:true});
    });
    setTimeout(window.__releaseAds,25000);
  }catch(e){}
})();
//

