//
/* =========================================================
   FONT SIZE CONTROL
   ========================================================= */

function changeFontSize(step) {

  const postBody = document.getElementById('postBody');

  if (!postBody) return;

  /* =========================
     الإعدادات
     ========================= */

  const defaultSize = 16;
  const minSize = 10;
  const maxSize = 60;
  const stepSize = 1;

  /* =========================
     الحجم الحالي
     ========================= */

  let currentSize = parseFloat(
    postBody.getAttribute('data-font-size')
  );

  if (isNaN(currentSize)) {
    currentSize = defaultSize;
  }

  /* =========================
     الحجم الجديد
     ========================= */

  const newSize = Math.min(
    maxSize,
    Math.max(
      minSize,
      currentSize + (step * stepSize)
    )
  );

  /* =========================
     حفظ القيمة
     ========================= */

  postBody.setAttribute(
    'data-font-size',
    newSize
  );

  /* =========================
     العناصر النصية
     ========================= */

  const textElements = postBody.querySelectorAll(
    'p, li, td, th, blockquote, q, span, a, strong, b, em, i, small, label, note, ref, qu, ans, figcaption'
  );

  textElements.forEach(function(element) {

    /*
     * لا نغير أي نص موجود داخل العناوين
     */
    if (
      element.closest(
        'h1, h2, h3, h4, h5, h6'
      )
    ) {
      return;
    }

    /*
     * تطبيق الحجم الجديد
     */
    element.style.setProperty(
      'font-size',
      newSize + 'px',
      'important'
    );

  });

  /* =========================
     تحديث الحالة البصرية
     ========================= */

  updateFontButtons(
    newSize,
    minSize,
    maxSize
  );
}

/* =========================================================
   تحديث أزرار A− / A+
   ========================================================= */

function updateFontButtons(
  currentSize,
  minSize,
  maxSize
) {

  const decreaseBtn = document.querySelector(
    '.font-btn[data-font-action="decrease"]'
  );

  const increaseBtn = document.querySelector(
    '.font-btn[data-font-action="increase"]'
  );

  if (decreaseBtn) {

    decreaseBtn.disabled =
      currentSize <= minSize;

  }

  if (increaseBtn) {

    increaseBtn.disabled =
      currentSize >= maxSize;

  }

}

/* 2. حساب وقت القراءة التلقائي */
document.addEventListener('DOMContentLoaded', () => {
  const postBody = document.getElementById('postBody');
  const timeHolder = document.getElementById('readingTime');
  if (postBody && timeHolder) {
    const text = postBody.innerText.trim();
    const wordCount = text.split(/\s+/).length;
    const readingTime = Math.ceil(wordCount / 200); // متوسط 200 كلمة بالدقيقة
    timeHolder.innerText = readingTime;
  }
});
