(function () {

  const button = document.getElementById('backToTop');

  if (!button) return;

  window.addEventListener('scroll', function () {

    if (window.scrollY > 500) {
      button.classList.add('show');
    } else {
      button.classList.remove('show');
    }

  }, { passive: true });

  button.addEventListener('click', function () {

    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });

  });

})();
