(function () {

  const container = document.getElementById('relatedPosts');
  const postBody = document.getElementById('postBody');
  if (!container) return;

  const currentUrl = window.location.href.split('?')[0];
  const label = container.getAttribute('data-label');
  if (!label) { container.innerHTML = ''; return; }

  const feedUrl = '/feeds/posts/summary/-/' + encodeURIComponent(label) +
    '?alt=json-in-script&max-results=7&callback=showRelatedPosts';

  window.showRelatedPosts = function (data) {
    const entries = data.feed.entry || [];
    const posts = entries.filter(function (entry) {
      const link = (entry.link || []).find(function (l) { return l.rel === 'alternate'; });
      return link && link.href.split('?')[0] !== currentUrl;
    }).slice(0, 6);

    if (!posts.length) { container.innerHTML = ''; return; }

    let html = '';
    posts.forEach(function (post) {
      const link = (post.link || []).find(function (l) { return l.rel === 'alternate'; });
      if (!link) return;
      const title = post.title.$t;
      let image = '';
      if (post.media$thumbnail) {
        image = post.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w400-rw/');
      }
      html += '<a class="related-card" href="' + link.href + '">' +
        (image ? '<img src="' + image + '" alt="' + title.replace(/"/g, '&quot;') + '" width="400" height="250" decoding="async" loading="lazy">' : '') +
        '<span class="related-card-title">' + title + '</span></a>';
    });
    container.innerHTML = html;

    /* إدراج كارت واحد جوه متن المقال بعد الفقرة التالتة */
if (postBody && posts.length > 0) {
  const headings = postBody.querySelectorAll('h2');

  if (headings.length >= 2) {
    const pick = posts[0];
    const link = (pick.link || []).find(function (l) {
      return l.rel === 'alternate';
    });

    if (link) {
      const inlineCard = document.createElement('div');

      inlineCard.className = 'inline-related-card';

      inlineCard.innerHTML =
        '<span class="inline-related-label">📖 اقرأ أيضًا</span>' +
        '<a href="' + link.href + '">' + pick.title.$t + '</a>';

      /* تحديد منتصف عناوين المقال */
      const middleIndex = Math.floor(headings.length / 2);

      /* وضع الكارت قبل العنوان الموجود بعد المنتصف */
      headings[middleIndex].insertAdjacentElement(
        'beforebegin',
        inlineCard
      );
    }
  }
}
  };

  const script = document.createElement('script');
  script.src = feedUrl;
  document.body.appendChild(script);

})();
