document.addEventListener('DOMContentLoaded', function () {

  var menuBtn = document.getElementById('sideMenuBtn');
  var menuClose = document.getElementById('sideMenuClose');
  var menu = document.getElementById('sideMenu');
  var overlay = document.getElementById('sideMenuOverlay');
  menu.inert = true;
  var searchInput = document.getElementById('sideMenuSearch');
  var searchBtn = document.getElementById('sideMenuSearchBtn');

  function openMenu() {
    menu.classList.add('open');
    overlay.classList.add('show');
    document.body.classList.add('menu-open');
    menu.inert = false;
    menu.setAttribute('aria-hidden', 'false');
    overlay.setAttribute('aria-hidden', 'false');
    menuBtn.setAttribute('aria-expanded', 'true');
    menuBtn.setAttribute('aria-label', 'إغلاق القائمة');
    menuClose.focus();
  }

  function closeMenu() {
    var wasOpen = menu.classList.contains('open');
    menu.classList.remove('open');
    overlay.classList.remove('show');
    document.body.classList.remove('menu-open');
    menu.inert = true;
    menu.setAttribute('aria-hidden', 'true');
    overlay.setAttribute('aria-hidden', 'true');
    menuBtn.setAttribute('aria-expanded', 'false');
    menuBtn.setAttribute('aria-label', 'فتح القائمة');
    if (wasOpen) menuBtn.focus();
  }

  if (menuBtn) menuBtn.addEventListener('click', openMenu);
  if (menuClose) menuClose.addEventListener('click', closeMenu);
  if (overlay) overlay.addEventListener('click', closeMenu);

  document.addEventListener('keydown', function (e) {
    if (!menu.classList.contains('open')) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      closeMenu();
      return;
    }
    if (e.key === 'Tab') {
      var focusable = menu.querySelectorAll('a[href], button:not([disabled]), input:not([disabled])');
      var first = focusable[0];
      var last = focusable[focusable.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });

  if (searchBtn) {
    searchBtn.addEventListener('click', function (event) {
      event.preventDefault();
      var q = searchInput.value.trim();
      if (q !== '') {
        window.location.href = '/search?q=' + encodeURIComponent(q);
      } else {
        searchInput.focus();
      }
    });
  }

  if (searchInput) {
    searchInput.addEventListener('keypress', function (e) {
      if (e.key === 'Enter') searchBtn.click();
    });
  }

});
