/* ارتفاع الأشرطة الثابتة أعلى الشاشة: العنوان يستقر تحتها بعد الضغط على جدول المحتويات */
function setStickyOffset() {
  var m = 0;
  ['.app-header', '.category-bar-wrapper'].forEach(function (s) {
    var e = document.querySelector(s);
    if (!e) return;
    var p = getComputedStyle(e).position;
    if (p === 'sticky' || p === 'fixed') m = Math.max(m, e.offsetHeight);
  });
  document.documentElement.style.setProperty('--sticky-h', (m + 16) + 'px');
}
addEventListener('resize', setStickyOffset, { passive: true });
document.addEventListener('DOMContentLoaded', function () {

  /* ============ جدول المحتويات ============ */
  setStickyOffset();
  var postBody = document.getElementById('postBody');
  var tocList = document.getElementById('tocList');

  if (postBody && tocList) {
    var headings = postBody.querySelectorAll('h2, h3');
    if (headings.length > 0) {
      tocList.innerHTML = '';
      headings.forEach(function (h, i) {
        var id = 'toc-heading-' + i;
        h.id = id;
        var a = document.createElement('a');
        a.href = '#' + id;
        a.textContent = h.textContent;
        a.className = h.tagName === 'H3' ? 'toc-h3' : 'toc-h2';
        a.addEventListener('click', function (e) {
          e.preventDefault();
          setStickyOffset();
          document.getElementById(id).scrollIntoView({ behavior: 'smooth', block: 'start' });
          history.pushState(null, '', '#' + id);
        });
        var li = document.createElement('li');
        li.appendChild(a);
        tocList.appendChild(li);
      });

      var tocLinks = tocList.querySelectorAll('a');
      window.addEventListener('scroll', function () {
        var current = null;
        headings.forEach(function (h) {
          if (h.getBoundingClientRect().top < 120) current = h.id;
        });
        tocLinks.forEach(function (a) {
          a.classList.toggle('active', a.getAttribute('href') === '#' + current);
        });
      }, { passive: true });

    } else {
      tocList.innerHTML = '<li class="toc-empty">لا يوجد عناوين فرعية في هذا المقال</li>';
    }
  }
  /* ============ آخر التعليقات ============ */
  var rcList = document.getElementById('recentCommentsList');
  if (rcList) {
    window.showRecentComments = function (data) {
      var entries = data.feed.entry || [];
      if (!entries.length) {
        rcList.innerHTML = '<div class="rc-loading">لا توجد تعليقات بعد</div>';
        return;
      }
      var html = '';
      entries.forEach(function (entry) {
        var link = (entry.link || []).find(function (l) { return l.rel === 'alternate'; });
        if (!link) return;
        var author = entry.author && entry.author[0] ? entry.author[0].name.$t : 'زائر';
        var text = entry.content ? entry.content.$t.replace(/<[^>]+>/g, '') : '';
        html += '<a class="recent-comment-item" href="' + link.href + '">' +
                  '<div class="rc-author">' + author + '</div>' +
                  '<div class="rc-snippet">' + text + '</div>' +
                '</a>';
      });
      rcList.innerHTML = html;
    };
    window.__lazyInit = window.__lazyInit || {};
    window.__lazyInit.comments = function () {
      var sc = document.createElement('script');
      sc.async = true;
      sc.src = '/feeds/comments/default?alt=json-in-script&max-results=5&callback=showRecentComments';
      sc.onerror = function () {
        rcList.innerHTML = '<div class="rc-loading">تعذر تحميل التعليقات <button class="lazy-retry" data-retry="comments" type="button">إعادة المحاولة</button></div>';
      };
      document.body.appendChild(sc);
    };
  }

});
