(function () {
'use strict';
var KEY='blogNotifState',DWELL=45,QUICK=5,SCROLL=0.25,IDLE=60000,GAP=1800000,MAXN=30,HOUR=3600,FEED_MAX=50,WEEK=604800000;
var LABELS={'welcome':'ترحيب','return-milestone':'شكر','missed':'جديد','recommendation':'مقترح لك','quick-exit':'رأيك يهمنا','time-thanks':'شكر'};
var THANKS={dislike:'شكرًا لملاحظتك، ستساعدنا على تحسين المحتوى. 🙏','continue':'يسعدنا اهتمامك! يمكنك استكمال المقال في أي وقت. 📖',dismissed:'لا مشكلة، شكرًا لوقتك! 🌿'};
var FORM_URL='https://docs.google.com/forms/d/e/1FAIpQLSftoTbLINCV9QLaqW-ffno1wnOogKyi4Dl8o20dKOedVmR0eA/formResponse';
var FF={url:'entry.328791941',title:'entry.2138270930',reason:'entry.1342271296'};
function $(id){return document.getElementById(id)}

/* مقال حقيقي فقط: /YYYY/MM/slug.html (الصفحات الثابتة /p/ مستبعدة) */
function isPostUrl(u){try{var p=new URL(u,location.href).pathname;return /^\/\d{4}\/\d{2}\/[^\/]+\.html$/.test(p)}catch(e){return false}}

/* إرسال الردود إلى Google Forms (sendBeacon يؤكد وضع الطلب في الطابور فقط) */
function sendFeedback(url,title,reason){if(!url||!reason)return;try{var b=new URLSearchParams();b.append(FF.url,url);b.append(FF.title,title||'');b.append(FF.reason,reason);
if(navigator.sendBeacon&&navigator.sendBeacon(FORM_URL,b))return;
if(window.fetch)window.fetch(FORM_URL,{method:'POST',mode:'no-cors',body:b,keepalive:true}).catch(function(){})}catch(e){}}

/* ===== الحالة ===== */
function defaultState(){return{firstVisitDone:false,lastVisitAt:null,lastVisitDay:null,visitStreak:0,lastMilestoneKey:'',seen:[],recommended:[],notifications:[],deleted:[],pendingQuickExit:null,pendingRecommendation:null,activeMs:0,hourNoticeSent:false,sessionStartedAt:0,lastActivityAt:0,sessionDay:'',sessionId:'',dislikeRatings:[],lastWelcomeArticle:null,clearedAt:0}}
function loadState(){try{var raw=localStorage.getItem(KEY);if(!raw)return defaultState();var s=JSON.parse(raw);if(!s||typeof s!=='object')return defaultState();var b=defaultState();
Object.keys(b).forEach(function(k){if(typeof s[k]!=='undefined')b[k]=s[k]});
['seen','recommended','notifications','deleted','dislikeRatings'].forEach(function(k){if(!Array.isArray(b[k]))b[k]=[]});return b}catch(e){return defaultState()}}

var state=loadState(),lastActivityAt=Date.now(),activeStart=Date.now(),activeDelta=0,activeVisible=document.visibilityState==='visible';
var pageIsPost=!!$('postBody')&&isPostUrl(location.href),currentPostUrl=pageIsPost?safeArticleUrl(location.href):'';
var og=document.querySelector('meta[property="og:title"]'),currentPostTitle=((og&&og.content)||document.title||'هذا المقال').trim();
var currentPostLabels=getCurrentPostLabels(),quickExitHandled=false;
var artMs=0,artTick=Date.now(),artVisible=document.visibilityState==='visible',artScroll=0,artRead=false;

/* ===== دمج الحالة بين التابات ===== */
function urlOf(i){return typeof i==='string'?i:(i&&i.url)||''}
function mergeUrls(mine,theirs){var k={};mine.forEach(function(i){k[urlOf(i)]=1});(theirs||[]).forEach(function(i){var u=urlOf(i);if(u&&!k[u]){k[u]=1;mine.push(i)}});return mine}
function mergeNotifications(mine,theirs){var by={};mine.forEach(function(n){if(n&&n.id)by[n.id]=n});
(theirs||[]).forEach(function(n){if(!n||!n.id)return;var e=by[n.id];if(!e){by[n.id]=n;mine.push(n);return}if(n.read)e.read=true;if(n.answered&&!e.answered)e.answered=n.answered});
return mine.sort(function(a,b){return(a.time||0)-(b.time||0)})}
function saveState(){try{var s=JSON.parse(localStorage.getItem(KEY)||'null');
if(s&&typeof s==='object'){
state.clearedAt=Math.max(state.clearedAt||0,s.clearedAt||0);
var dl=state.deleted||[];(s.deleted||[]).forEach(function(i){if(dl.indexOf(i)<0)dl.push(i)});state.deleted=dl.slice(-200);
state.seen=mergeUrls(state.seen,s.seen);state.recommended=mergeUrls(state.recommended,s.recommended);state.dislikeRatings=mergeUrls(state.dislikeRatings,s.dislikeRatings);
state.notifications=mergeNotifications(state.notifications,s.notifications);
if(s.firstVisitDone)state.firstVisitDone=true;
if(s.lastVisitAt&&(!state.lastVisitAt||s.lastVisitAt>state.lastVisitAt)){state.lastVisitAt=s.lastVisitAt;state.lastVisitDay=s.lastVisitDay;state.visitStreak=s.visitStreak;state.lastMilestoneKey=s.lastMilestoneKey}
state.lastActivityAt=Math.max(Number(state.lastActivityAt||0),Number(s.lastActivityAt||0));
if(s.sessionId&&s.sessionId===state.sessionId)state.hourNoticeSent=!!(state.hourNoticeSent||s.hourNoticeSent)}
var same=!!(s&&s.sessionId&&s.sessionId===state.sessionId);
state.activeMs=(same?Number(s.activeMs||0):Number(state.activeMs||0))+activeDelta;activeDelta=0;
/* الإشعارات الأقدم من وقت "حذف الكل" لا تعود من أي تاب آخر */
state.notifications=state.notifications.filter(function(n){return(n.time||0)>state.clearedAt&&(state.deleted||[]).indexOf(n.id)<0}).slice(-MAXN);
localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}}

/* ===== أدوات عامة ===== */
function safeArticleUrl(url){if(!url)return'';try{var p=new URL(url,location.href);if(!/^https?:$/.test(p.protocol))return'';
if(p.hostname.replace(/^www\./,'')!==location.hostname.replace(/^www\./,''))return'';return location.origin+p.pathname.replace(/\/$/,'')}catch(e){return''}}
function two(n){return('0'+n).slice(-2)}
function todayKey(d){d=d||new Date();return d.getFullYear()+'-'+two(d.getMonth()+1)+'-'+two(d.getDate())}
function genId(){return'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function getEntryUrl(e){var l=e&&e.link?e.link:[];for(var i=0;i<l.length;i++)if(l[i].rel==='alternate'&&l[i].href)return safeArticleUrl(l[i].href);return''}
function getEntryTitle(e){return e&&e.title&&e.title.$t?e.title.$t:'مقال جديد'}
function getEntryLabels(e){return(e&&e.category?e.category:[]).map(function(c){return String(c.term||'').trim()}).filter(Boolean)}
function labelUrl(l){return location.origin+'/search/label/'+encodeURIComponent(l)}
function getCurrentPostLabels(){var f=[];['.post-labels a','a[rel="tag"]'].forEach(function(s){var n=document.querySelectorAll(s);for(var i=0;i<n.length;i++){var t=(n[i].textContent||'').trim();if(t&&f.indexOf(t)===-1)f.push(t)}});return f}
function hasUrl(list,url){if(!url)return false;for(var i=0;i<list.length;i++)if(urlOf(list[i])===url)return true;return false}
function isSeen(u){return hasUrl(state.seen,u)}
function wasRecommended(u){return hasUrl(state.recommended,u)}
function recordSeen(u){if(!u||isSeen(u))return;state.seen.push(u);saveState()}
function markRecommended(u){if(!u||wasRecommended(u))return;state.recommended.push({url:u,time:Date.now()});saveState()}
function getSessionInfo(){var now=Date.now(),last=Number(state.lastActivityAt||0);
if(!state.sessionId||!last||now-last>GAP){state.sessionId=genId();state.sessionStartedAt=now;state.activeMs=0;state.hourNoticeSent=false;state.sessionDay=todayKey()}
state.lastActivityAt=now;saveState()}

/* ===== الإشعارات والواجهة ===== */
function unreadCount(){return state.notifications.filter(function(n){return!n.read}).length}
function updateBadge(){var b=$('notifBadge');if(!b)return;var c=unreadCount();b.style.display=c?'flex':'none';b.textContent=c>9?'9+':String(c)}
function timeAgo(t){var d=Math.max(0,Math.floor((Date.now()-t)/1000));return d<60?'الآن':d<3600?Math.floor(d/60)+' د':d<86400?Math.floor(d/3600)+' س':Math.floor(d/86400)+' يوم'}
function pushNotif(n){n.id=genId();n.time=Date.now();n.read=false;state.notifications.push(n);saveState();renderPanel();showToast(n);return true}

function renderPanel(){var list=$('notifPanelList');if(!list)return;
if(!state.notifications.length){list.innerHTML='<div class="notif-empty">لا توجد إشعارات جديدة حاليًا 🌿</div>';updateBadge();return}
var h='';
state.notifications.slice().sort(function(a,b){return b.time-a.time}).forEach(function(n){
var type=String(n.type||'general').replace(/[^a-z-]/g,''),id=esc(n.id),q=n.type==='quick-exit';
var btn=function(a,t,p){return'<button'+(p?' class="primary"':'')+' data-action="'+a+'" data-id="'+id+'">'+esc(t)+'</button>'};
h+='<div class="notif-item type-'+type+(n.read?'':' unread')+'" data-id="'+id+'"><div class="notif-item-top"><span class="notif-icon">'+esc(n.icon||'🔔')+'</span><div class="notif-body">'
+'<div class="notif-kicker"><span class="notif-kicker-label">'+esc(n.kicker||LABELS[n.type]||'إشعار')+'</span><span class="notif-kicker-end"><span class="notif-time">'+timeAgo(n.time)+'</span><button class="notif-del" type="button" data-action="delete" data-id="'+id+'" aria-label="حذف الإشعار"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6M14 11v6"/></svg></button></span></div>'
+'<div class="notif-title">'+esc(n.title)+'</div>'
+(n.text?'<div class="notif-text">'+esc(n.text)+'</div>':'')
+(n.article?'<div class="notif-article">'+esc(n.article)+'</div>':'')
+(n.tags&&n.tags.length?'<div class="notif-tags">'+n.tags.slice(0,3).map(function(t){return'<span>'+esc(t)+'</span>'}).join('')+'</div>':'');
if(q&&!n.answered)h+='<div class="notif-actions">'+btn('continue','أريد إكمال قراءته',1)+btn('dislike','لم يعجبني المقال')+btn('dismiss','ليس الآن')+'</div>';
else if(q)h+='<div class="notif-thanks">'+(THANKS[n.answered]||'')+'</div>';
else if(n.url&&!n.answered)h+='<div class="notif-actions">'+btn('open',n.cta||'اقرأ المقال',1)+(n.type==='missed'?btn('dismiss','ليس الآن'):'')+'</div>';
h+='</div></div></div>'});
list.innerHTML=h;updateBadge()}

function showToast(n){var t=$('notifToast');if(!t)return;
var i=document.createElement('span');i.className='toast-icon';i.textContent=n.icon||'🔔';
var x=document.createElement('span');x.className='toast-text';x.textContent=n.title||'إشعار جديد';
t.innerHTML='';t.appendChild(i);t.appendChild(x);
t.setAttribute('aria-hidden','false');t.setAttribute('tabindex','0');
t.className=t.className.replace(/\btype-\S+/g,'').replace(/\s+/g,' ').trim();
var ty=String(n.type||'').replace(/[^a-z-]/g,'');if(ty)t.classList.add('type-'+ty);
t.classList.add('show');t.onclick=function(){openPanel();t.classList.remove('show');t.setAttribute('aria-hidden','true');t.setAttribute('tabindex','-1')};
t.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();t.click()}};
setTimeout(function(){t.classList.remove('show');t.setAttribute('aria-hidden','true');t.setAttribute('tabindex','-1')},6000)}

function openPanel(){var p=$('notifPanel'),o=$('notifPanelOverlay'),bell=$('notifBellBtn'),close=$('notifPanelClose');
if(p){p.inert=false;p.setAttribute('aria-hidden','false');p.classList.add('open')}
if(o){o.setAttribute('aria-hidden','false');o.classList.add('show')}
if(bell){bell.setAttribute('aria-expanded','true')}
if(close)close.focus();
renderPanel();
setTimeout(function(){state.notifications.forEach(function(n){n.read=true});saveState();updateBadge()},1200)}
function closePanel(){var p=$('notifPanel'),o=$('notifPanelOverlay'),bell=$('notifBellBtn');
if(p){p.classList.remove('open');p.setAttribute('aria-hidden','true');p.inert=true}
if(o){o.classList.remove('show');o.setAttribute('aria-hidden','true')}
if(bell){bell.setAttribute('aria-expanded','false');bell.focus()}}

/* حذف كل الإشعارات من الواجهة ومن localStorage، دون إعادة رسالة الترحيب (firstVisitDone تبقى true) */
function clearAll(){if(!confirm('هل تريد حذف جميع الإشعارات؟'))return;
state.notifications=[];state.pendingQuickExit=null;state.pendingRecommendation=null;state.clearedAt=Date.now();
saveState();renderPanel();var t=$('notifToast');if(t)t.classList.remove('show')}

/* ===== جلب المقالات ===== */
function fetchFeed(url,cb){var done=false;
function fin(d){if(done)return;done=true;try{cb(d&&d.feed&&Array.isArray(d.feed.entry)?d.feed.entry:[])}catch(e){}}
if(window.fetch){window.fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json'}}).then(function(r){if(!r.ok)throw 0;return r.json()}).then(fin).catch(function(){fin(null)});return}
var cn='__bnf'+Date.now()+Math.floor(Math.random()*1000),s=document.createElement('script'),t=setTimeout(function(){cl();fin(null)},10000);
function cl(){clearTimeout(t);try{delete window[cn]}catch(e){window[cn]=undefined}if(s.parentNode)s.parentNode.removeChild(s)}
window[cn]=function(d){cl();fin(d)};s.onerror=function(){cl();fin(null)};
s.src=url.replace(/([?&])alt=json(?:-in-script)?/,'$1alt=json-in-script')+(url.indexOf('?')===-1?'?':'&')+'callback='+cn;document.body.appendChild(s)}
function fetchLatestPosts(cb,max){fetchFeed('/feeds/posts/summary?alt=json&max-results='+(max||FEED_MAX),cb)}

/* ===== الزيارة الأولى ===== */
function handleFirstVisit(){if(state.firstVisitDone)return;
state.firstVisitDone=true;state.lastVisitAt=new Date().toISOString();state.lastVisitDay=todayKey();state.visitStreak=1;saveState();
fetchLatestPosts(function(es){var base={type:'welcome',icon:'👋',title:'أهلًا بك في موقع د. مؤمن'};
if(!es.length){base.text='نتمنى لك رحلة قراءة ممتعة ومفيدة في موضوعات الصحة والدواء.';pushNotif(base);return}
var v=es.filter(function(e){return getEntryUrl(e)});if(!v.length)v=es;
var p=v[Math.floor(Math.random()*v.length)],u=getEntryUrl(p);state.lastWelcomeArticle=u;saveState();
base.text='ابدأ رحلتك بقراءة:';base.article=getEntryTitle(p);base.cta='ابدأ القراءة';base.url=u;pushNotif(base)},10)}

function missedTitle(c){return c===1?'لقد فاتك مقال جديد':c===2?'لقد فاتك مقالان جديدان':c<=10?'لقد فاتك '+c+' مقالات جديدة':'لقد فاتك '+c+' مقالًا جديدًا'}
function streakTitle(n){return n===2?'يومان متتاليان معنا':n<=10?n+' أيام متتالية معنا':n+' يومًا متتاليًا معنا'}
function milestoneInfo(s){
if(s>=365&&s%365===0)return{key:'year-'+s/365,icon:'🏆',kicker:'إنجاز',title:'سنة كاملة معنا!',text:'نعتز بثقتك ونشكرك على رفقتك الطويلة.'};
if(s>=30&&s%30===0)return{key:'month-'+s/30,icon:'🌟',kicker:'إنجاز',title:'شهر من الزيارات المتواصلة',text:'يسعدنا استمرارك، ونتمنى أن تجد دائمًا ما يفيدك.'};
if(s%7===0)return{key:'week-'+s/7,icon:'🎖️',kicker:'إنجاز',title:'أسبوع من الزيارات المتواصلة',text:'شكرًا لثقتك ووجودك معنا.'};
var t={2:'سعداء بعودتك! نأمل أن تجد ما يفيدك.',3:'شكرًا لاهتمامك بالمعرفة الصحية.',4:'مرحبًا بعودتك، ونتمنى لك قراءة ممتعة.',5:'يسعدنا وجودك بين قرائنا.',6:'نتمنى لك يومًا طيبًا وقراءة نافعة.'};
return s>=2&&s<=6?{key:'day-'+s,icon:'🔥',kicker:'استمرار',title:streakTitle(s),text:t[s]}:null}

/* ===== الزيارات اللاحقة ===== */
function handleReturningVisit(){var now=new Date(),today=todayKey(now),prevDay=state.lastVisitDay,prev=state.lastVisitAt;
if(!prev){state.lastVisitAt=now.toISOString();state.lastVisitDay=today;saveState();return}
if(prevDay!==today){
/* نعدّ الأيام التي فُتح فيها الموقع فعلًا فقط؛ الأيام الغائبة لا تُحسب ولا تصفّر العدّاد */
state.visitStreak=Number(state.visitStreak||1)+1;
var m=milestoneInfo(state.visitStreak);
if(m&&state.lastMilestoneKey!==m.key){pushNotif({type:'return-milestone',icon:m.icon,kicker:m.kicker,title:m.title,text:m.text});state.lastMilestoneKey=m.key}}
state.lastVisitAt=now.toISOString();state.lastVisitDay=today;saveState();
var since=new Date(prev).getTime();
fetchLatestPosts(function(es){
var un=es.filter(function(e){var u=getEntryUrl(e),p=e&&e.published&&e.published.$t?new Date(e.published.$t).getTime():0;return u&&u!==currentPostUrl&&p>since&&!isSeen(u)&&!wasRecommended(u)});
if(!un.length)return;var pick=un[0],u=getEntryUrl(pick);
pushNotif({type:'missed',icon:'📬',title:missedTitle(un.length),text:(un.length===1?'تمت إضافته':'تمت إضافتها')+' منذ آخر زيارة لك، '+(un.length===1?'وهو:':'من ضمنها:'),article:getEntryTitle(pick),cta:'اقرأه الآن',url:u});
markRecommended(u)},FEED_MAX)}

/* ===== التوصية: تُنشأ بعد مغادرة المقال، من نفس فئته، دون تكرار أو مقالات مقروءة ===== */
function processPendingRecommendation(){var p=state.pendingRecommendation;if(!p||!p.url)return;
var src=safeArticleUrl(p.url);if(!src||!isPostUrl(src)){state.pendingRecommendation=null;saveState();return}if(src===currentPostUrl)return;
state.pendingRecommendation=null;saveState();
if(state.notifications.some(function(n){return n.type==='recommendation'&&n.srcUrl===src}))return;
fetchLatestPosts(function(es){
var se=null;es.forEach(function(e){if(getEntryUrl(e)===src)se=e});
var labels=se?getEntryLabels(se):[];if(!labels.length)labels=p.labels||[];if(!labels.length)return;
var title=p.title||(se?getEntryTitle(se):'هذا المقال');
(function next(i){
if(i>=labels.length){var l=labels[0];
pushNotif({type:'recommendation',icon:'📚',title:'مقال يناسب اهتمامك',text:'لقد اطلعت مؤخرًا على مقال «'+title+'» ضمن فئة «'+l+'».',article:l,tags:[l],cta:'استعرض جميع المقالات ضمن هذه الفئة',url:labelUrl(l),srcUrl:src});return}
fetchFeed('/feeds/posts/summary/-/'+encodeURIComponent(labels[i])+'?alt=json&max-results=50',function(fe){
if(!fe.length)return;
var c=fe.filter(function(e){var u=getEntryUrl(e);return u&&u!==src&&u!==currentPostUrl&&!isSeen(u)&&!wasRecommended(u)});
if(!c.length){next(i+1);return}
var pick=c[Math.floor(Math.random()*c.length)],u=getEntryUrl(pick);
pushNotif({type:'recommendation',icon:'📚',title:'مقال يناسب اهتمامك',text:'لقد اطلعت مؤخرًا على مقال «'+title+'» ضمن فئة «'+labels[i]+'»، لذا نقترح عليك مقالًا قد يعجبك أيضًا:',article:getEntryTitle(pick),tags:[labels[i]],cta:'اقرأ المقال',url:u,srcUrl:src});
markRecommended(u)})})(0)},FEED_MAX)}

/* ===== تتبع قراءة المقال ===== */
function updateScroll(){var a=$('postBody');if(!a)return;
var st=window.pageYOffset||document.documentElement.scrollTop||0,vh=window.innerHeight||document.documentElement.clientHeight||0,r=a.getBoundingClientRect();
var pr=Math.max(0,Math.min(1,(st+vh-(r.top+st))/Math.max(a.scrollHeight||0,r.height||0,1)));if(pr>artScroll)artScroll=pr}
function trackArticleReading(){if(!pageIsPost||!currentPostUrl||artRead)return;
var now=Date.now();if(artVisible)artMs+=Math.min(Math.max(0,now-artTick),3000);
artTick=now;artVisible=document.visibilityState==='visible';updateScroll();
if(artMs>=DWELL*1000&&artScroll>=SCROLL){artRead=true;var already=isSeen(currentPostUrl);recordSeen(currentPostUrl);
if(state.pendingQuickExit&&state.pendingQuickExit.url===currentPostUrl)state.pendingQuickExit=null;
if(!already)state.pendingRecommendation={url:currentPostUrl,title:currentPostTitle,labels:currentPostLabels,time:Date.now()};saveState()}}

/* ===== المغادرة المبكرة ===== */
function scheduleQuickExitPrompt(){
if(!pageIsPost||!currentPostUrl||artRead||isSeen(currentPostUrl)||quickExitHandled)return;
var el=Math.floor(artMs/1000);if(el<QUICK||el>=DWELL)return;
if(state.pendingQuickExit&&state.pendingQuickExit.url===currentPostUrl)return;
quickExitHandled=true;state.pendingQuickExit={url:currentPostUrl,title:currentPostTitle,time:Date.now(),visibleSeconds:el};saveState()}
function showPendingQuickExit(){var p=state.pendingQuickExit;if(!p||!p.url)return;
p.url=safeArticleUrl(p.url);if(!p.url||!isPostUrl(p.url)){state.pendingQuickExit=null;saveState();return}
if(p.url===currentPostUrl)return;
if(Date.now()-Number(p.time||0)>WEEK||isSeen(p.url)||state.notifications.some(function(n){return n.type==='quick-exit'&&n.articleUrl===p.url})){state.pendingQuickExit=null;saveState();return}
pushNotif({type:'quick-exit',icon:'💬',kicker:'رأيك يهمنا',title:'لقد غادرت سريعًا',text:'لاحظنا أنك أغلقت هذا المقال دون إكماله. هل المقال لم يعجبك، أم تريد إكمال قراءته لاحقًا؟',article:p.title,url:p.url,articleUrl:p.url,articleTitle:p.title,answered:null});
state.pendingQuickExit=null;saveState()}

/* ===== حذف إشعار واحد (من الواجهة ومن localStorage، ولا يعود من تاب آخر) ===== */
function deleteNotif(id){if(!id)return;state.notifications=state.notifications.filter(function(x){return x.id!==id});
state.deleted=(state.deleted||[]);if(state.deleted.indexOf(id)<0)state.deleted.push(id);saveState();renderPanel()}
/* ===== أزرار الإشعارات ===== */
function handlePanelClick(e){var b=e.target.closest&&e.target.closest('button[data-action]');if(!b)return;
var n=state.notifications.filter(function(x){return x.id===b.getAttribute('data-id')})[0];if(!n)return;
var a=b.getAttribute('data-action'),u=safeArticleUrl(n.url);
if(a==='delete'){deleteNotif(n.id);return}
if(a==='open'){if(u)location.href=u;return}
if(n.answered)return;
n.answered=a==='dislike'?'dislike':a==='continue'?'continue':'dismissed';
var fb=a==='dislike'?'dislike':a==='continue'?'continue':'dismiss';
if(a==='dislike'){if(n.articleUrl&&!hasUrl(state.dislikeRatings,n.articleUrl))state.dislikeRatings.push({url:n.articleUrl,time:Date.now()});else fb=''}
saveState();renderPanel();
if(n.type==='quick-exit')sendFeedback(n.articleUrl,n.articleTitle,fb);
if(a==='continue'&&u)location.href=u}

/* ===== الوقت النشط ===== */
function accountActiveTime(){var now=Date.now();
if(activeVisible)activeDelta+=Math.max(0,Math.min(now,lastActivityAt+IDLE)-activeStart);
activeStart=now;activeVisible=document.visibilityState==='visible';saveState();
if(!state.hourNoticeSent&&state.activeMs>=HOUR*1000){pushNotif({type:'time-thanks',icon:'💚',title:'ساعة معنا… شكرًا لك',text:'قضيت ساعة نشطة في موقعنا، ونقدّر ثقتك واهتمامك.'});state.hourNoticeSent=true;saveState()}}
function onActivity(){var n=Date.now();if(n-lastActivityAt>IDLE)activeStart=n;lastActivityAt=n;state.lastActivityAt=n}

/* ===== البدء ===== */
function init(){var bell=$('notifBellBtn'),panel=$('notifPanel'),ov=$('notifPanelOverlay'),cl=$('notifPanelClose'),clr=$('notifClearAllBtn');
if(panel)panel.inert=true;
if(bell)bell.addEventListener('click',function(e){e.stopPropagation();openPanel()});
if(cl)cl.addEventListener('click',closePanel);
if(ov)ov.addEventListener('click',closePanel);
document.addEventListener('keydown',function(e){
if(!panel||!panel.classList.contains('open'))return;
if(e.key==='Escape'){e.preventDefault();closePanel();return}
if(e.key==='Tab'){
var candidates=panel.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),[tabindex]:not([tabindex="-1"])');
var focusable=Array.prototype.filter.call(candidates,function(el){return el.getClientRects().length>0});
var first=focusable[0],last=focusable[focusable.length-1];
if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
}
});
if(panel)panel.addEventListener('click',handlePanelClick);
/* زر "حذف جميع الإشعارات": يُنشأ تلقائيًا داخل اللوحة إن لم تضف له عنصرًا بالمعرّف notifClearAllBtn */
if(!clr&&panel){clr=document.createElement('button');clr.id='notifClearAllBtn';clr.className='notif-clear-all';clr.textContent='🗑️ حذف جميع الإشعارات';clr.style.cssText='display:block;width:calc(100% - 24px);margin:10px 12px;padding:10px;border:0;border-radius:10px;cursor:pointer;font:inherit';panel.appendChild(clr)}
if(clr)clr.addEventListener('click',clearAll);
getSessionInfo();updateBadge();renderPanel();showPendingQuickExit();processPendingRecommendation();
