window.__lazyInit = window.__lazyInit || {};
window.__lazyInit.poll = function () {
  var CURRENT_POLL = {
    id: 'poll-2026-08',
    question: 'إمتى بتحس انك محتاج تشرب مياة؟',
    options: [
      { id: 'a', label: '⏰ بشرب على فترات طول اليوم' },
      { id: 'b', label: '🍽️ لما باكل بشرب مع الأكل أو بعده' },
      { id: 'c', label: '💧 لما أحس إني عطشان' },
      { id: 'd', label: '😅 لما افتكر إني مشربتش من فترة' }
    ]
  };

  var qEl = document.getElementById('pollQuestionText');
  var optionsBox = document.getElementById('pollOptionsBox');
  var resultsBox = document.getElementById('pollResultsBox');
  var totalEl = document.getElementById('pollTotalVotes');
  if (!qEl) return;

  qEl.textContent = CURRENT_POLL.question;
  var voteKey = 'voted_' + CURRENT_POLL.id;
  var colors = ['var(--primary)', 'var(--secondary)', '#f59e0b', '#10b981', '#ec4899', '#8b5cf6'];

  function renderOptions() {
    var html = '';
    CURRENT_POLL.options.forEach(function (opt) {
      html += '<button class="poll-btn" data-id="' + opt.id + '">' + opt.label + '</button>';
    });
    optionsBox.innerHTML = html;
    optionsBox.querySelectorAll('.poll-btn').forEach(function (btn) {
      btn.addEventListener('click', function () { castVote(btn.getAttribute('data-id')); });
    });
  }

  function renderResults(data) {
    var total = 0;
    CURRENT_POLL.options.forEach(function (opt) {
      total += (data && data.options && data.options[opt.id] && data.options[opt.id].count) || 0;
    });
    total = total || 1;

    var html = '';
    CURRENT_POLL.options.forEach(function (opt, i) {
      var count = (data && data.options && data.options[opt.id] && data.options[opt.id].count) || 0;
      var pct = Math.round((count / total) * 100);
      var isMine = localStorage.getItem(voteKey) === opt.id;
      html += '<div class="poll-result-row' + (isMine ? ' poll-result-mine' : '') + '">' +
        '<div class="poll-result-top"><span>' + opt.label + (isMine ? ' <span class="poll-mine-tag">اخترته</span>' : '') + '</span><span class="poll-result-pct">' + pct + '%</span></div>' +
        '<div class="poll-bar"><div class="poll-bar-fill" style="width:' + pct + '%; background:' + colors[i % colors.length] + ';"></div></div>' +
        '</div>';
    });
    resultsBox.innerHTML = html;
    resultsBox.style.display = 'block';
    optionsBox.style.display = 'none';
    totalEl.textContent = '👥 إجمالي المشاركات: ' + (total === 1 && (!data || !data.options) ? 0 : total);
    totalEl.style.display = 'block';
  }

  function fetchResults() {
    window.ensureChatFirebase().then(function () {
      return firebase.database().ref('polls/' + CURRENT_POLL.id).once('value');
    }).then(function (snap) {
      renderResults(snap.val());
    }).catch(function (err) {
      console.error('Poll results failed to load:', err);
    });
  }

  function castVote(optId) {
    window.ensureChatFirebase().then(function () {
      return firebase.auth().signInAnonymously();
    }).then(function () {
      var ref = firebase.database().ref('polls/' + CURRENT_POLL.id);
      ref.transaction(function (current) {
        if (!current) { current = { question: CURRENT_POLL.question, options: {} }; }
        if (!current.options) current.options = {};
        CURRENT_POLL.options.forEach(function (opt) {
          if (!current.options[opt.id]) current.options[opt.id] = { label: opt.label, count: 0 };
        });
        current.options[optId].count = (current.options[optId].count || 0) + 1;
        return current;
      }, function (err, committed, snap) {
        if (!err && committed) {
          localStorage.setItem(voteKey, optId);
          renderResults(snap.val());
        }
      });
    });
  }

  if (localStorage.getItem(voteKey)) {
    fetchResults();
  } else {
    renderOptions();
  }
};
