document.addEventListener('DOMContentLoaded', function () {

  var toggleBtn = document.getElementById('chatToggleBtn');
  var panel = document.getElementById('chatPanel');
  var closeBtn = document.getElementById('chatPanelClose');
  var notifDot = document.getElementById('chatNotifDot');
if (!toggleBtn) return;
if (!notifDot) { notifDot = document.createElement('span'); notifDot.style.display = 'none'; }

  var gate = document.getElementById('chatNameGate');
  var main = document.getElementById('chatMain');
  var db, myUid, myName;
  var refs = {};
  var chatStarted = false;
  var currentThreadUid = null;
  var forcePublicScroll = false;

  function escapeHtml(s) { var d = document.createElement('div'); d.textContent = s; return d.innerHTML; }

  function playBeep() {
    try {
      var ctx = new (window.AudioContext || window.webkitAudioContext)();
      var osc = ctx.createOscillator(); var gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      osc.frequency.value = 880;
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35);
      osc.start(); osc.stop(ctx.currentTime + 0.35);
    } catch (e) {}
  }

  function notifyNewMessage(fromName) {
    playBeep();
    if (window.Notification && Notification.permission === 'granted') {
      new Notification('رسالة جديدة من ' + fromName);
    }
  }

  /* ===== فتح البانل ===== */
  function openPanel() {
    panel.classList.add('open');
    panel.setAttribute('aria-hidden', 'false');
    toggleBtn.setAttribute('aria-expanded', 'true');
    toggleBtn.setAttribute('aria-label', 'إغلاق دردشة المجتمع');
    document.body.classList.add('chat-open-lock');
    closeBtn.focus();
    if (window.Notification && Notification.permission === 'default') { Notification.requestPermission(); }

    gate.innerHTML = '<div aria-live="polite" class="chat-gate-loading" role="status">جاري الاتصال...</div>';
    gate.style.display = 'flex';
    main.style.display = 'none';

    window.ensureChatFirebase().then(function () {
      return firebase.auth().signInAnonymously();
    }).then(function (cred) {
      myUid = cred.user.uid;
      var savedName = localStorage.getItem('chat_name_' + myUid);
      if (savedName) { myName = savedName; startChat(); }
      else { showNameGate(); }
    }).catch(function (err) {
      console.error('Auth error:', err);
      gate.innerHTML = '<div aria-live="assertive" class="chat-gate-error" role="alert">تعذر الاتصال، حاولي تاني.</div>';
    });
  }

  function showNameGate() {
    gate.innerHTML =
      '<div class="chat-gate-icon">💬</div>' +
      '<p class="chat-gate-title">أهلًا بيك في دردشة المجتمع</p>' +
      '<p class="chat-gate-text">أدخل اسمك للانضمام:</p>' +
      '<input aria-label="اسمك في الدردشة" class="chat-name-input" id="chatNameInput" maxlength="20" placeholder="اسمك" type="text"/>' +
      '<button class="chat-name-btn" id="chatNameSubmit" type="button">دخول</button>';

    document.getElementById('chatNameSubmit').addEventListener('click', function () {
      var val = document.getElementById('chatNameInput').value.trim();
      if (!val) return;
      myName = val;
      localStorage.setItem('chat_name_' + myUid, myName);
      firebase.database().ref('users/' + myUid).set({ name: myName });
      startChat();
    });
    document.getElementById('chatNameInput').focus();
  }

  function closePanel() {
    panel.classList.remove('open');
    panel.setAttribute('aria-hidden', 'true');
    toggleBtn.setAttribute('aria-expanded', 'false');
    toggleBtn.setAttribute('aria-label', 'فتح دردشة المجتمع');
    document.body.classList.remove('chat-open-lock');
    toggleBtn.focus();
  }

  toggleBtn.addEventListener('click', openPanel);
  closeBtn.addEventListener('click', closePanel);
  document.addEventListener('keydown', function (event) {
    if (!panel.classList.contains('open')) return;
    if (event.key === 'Escape') {
      event.preventDefault();
      closePanel();
      return;
    }
    if (event.key === 'Tab') {
      var candidates = panel.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])');
      var focusable = Array.prototype.filter.call(candidates, function (el) {
        return el.getClientRects().length > 0;
      });
      var first = focusable[0];
      var last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    }
  });

  /* ===== بداية الشات (مرة واحدة بس) ===== */
  function startChat() {
    gate.style.display = 'none';
    main.style.display = 'flex';
    db = firebase.database();
    db.ref('users/' + myUid).set({ name: myName });

    if (chatStarted) { switchTab('online'); return; }
    chatStarted = true;

    var myPresenceRef = db.ref('presence/' + myUid);
    db.ref('.info/connected').on('value', function (snap) {
      if (snap.val() === true) {
        myPresenceRef.onDisconnect().remove();
        myPresenceRef.set({ name: myName });
      }
    });

    loadOnlineUsers();
    loadPublicChat();
    listenInbox();

    document.getElementById('tabOnline').addEventListener('click', function () { switchTab('online'); });
    document.getElementById('tabPublic').addEventListener('click', function () { switchTab('public'); });
    document.getElementById('tabPrivate').addEventListener('click', function () { switchTab('private'); loadConvList(); });

    document.getElementById('publicForm').addEventListener('submit', function (e) {
      e.preventDefault();
      var input = document.getElementById('publicInput');
      var text = input.value.trim();
      if (!text) return;
      forcePublicScroll = true;
      db.ref('chat/public').push({ uid: myUid, name: myName, text: text, time: Date.now() });
      input.value = '';
    });

    document.getElementById('backToConvList').addEventListener('click', function () { loadConvList(); });

    /* تفويض الأحداث: مرة واحدة بس على كل قائمة */
    document.getElementById('onlineList').addEventListener('click', function (e) {
      var item = e.target.closest('.online-item');
      if (!item) return;
      var uid = item.getAttribute('data-uid');
      var name = item.getAttribute('data-name');
      console.log('Opening chat with:', uid, name);
      switchTab('private');
      openPrivateThread(uid, name);
    });

    document.getElementById('convList').addEventListener('click', function (e) {
      var item = e.target.closest('.conv-item');
      if (!item) return;
      openPrivateThread(item.getAttribute('data-uid'), item.getAttribute('data-name'));
    });

    switchTab('online');
  }

  function switchTab(tab) {
    ['online', 'public', 'private'].forEach(function (t) {
      document.getElementById('tab' + t.charAt(0).toUpperCase() + t.slice(1)).classList.toggle('active', t === tab);
      document.getElementById(t + 'View').style.display = t === tab ? 'flex' : 'none';
    });
    if (tab === 'public') { scrollPublic(); }
  }

  /* تمرير غرفة الدردشة العامة لآخر رسالة */
  function scrollPublic() {
    var b = document.getElementById('publicMessages');
    if (!b) return;
    b.scrollTop = b.scrollHeight;
    requestAnimationFrame(function () { b.scrollTop = b.scrollHeight; });
    setTimeout(function () { b.scrollTop = b.scrollHeight; }, 150);
  }

  /* ===== المتصلين الآن ===== */
  function loadOnlineUsers() {
    var list = document.getElementById('onlineList');
    refs.presence = db.ref('presence');
    refs.presence.on('value', function (snap) {
      var html = '';
      snap.forEach(function (c) {
        if (c.key === myUid) return;
        var u = c.val();
        if (!u || !u.name) return;
        html += '<div class="online-item" data-uid="' + c.key + '" data-name="' + escapeHtml(u.name) + '">' +
          '<span class="online-dot"></span><span class="online-name">' + escapeHtml(u.name) + '</span>' +
          '<span class="online-msg-btn">مراسلة 💬</span></div>';
      });
      list.innerHTML = html || '<div class="conv-empty">لا يوجد متصلين حاليًا غيرك 👋</div>';
    }, function (err) { console.error('presence read failed:', err); });
  }

  /* ===== الغرفة العامة ===== */
  function loadPublicChat() {
    var box = document.getElementById('publicMessages');
    refs.public = db.ref('chat/public').limitToLast(50);
    refs.public.on('value', function (snap) {
      var msgs = [];
      snap.forEach(function (c) { msgs.push(c.val()); });
      var nearBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 160;
      box.innerHTML = msgs.map(function (m) {
        var mine = m.uid === myUid ? ' mine' : '';
        return '<div class="chat-msg' + mine + '"><span class="chat-msg-name">' + escapeHtml(m.name) + '</span><span class="chat-msg-text">' + escapeHtml(m.text) + '</span></div>';
      }).join('');
      if (nearBottom || forcePublicScroll) { box.scrollTop = box.scrollHeight; forcePublicScroll = false; }
    }, function (err) { console.error('public read failed:', err); });
  }

  /* ===== صندوق الوارد: عدّاد الرسائل الخاصة غير المقروءة ===== */
  var inboxMap = {};
  var inboxReady = false;
  function setUnreadBadges(n) {
    var label = n > 99 ? '99+' : String(n);
    notifDot.textContent = label;
    notifDot.style.display = n > 0 ? 'flex' : 'none';
    var badge = document.getElementById('privateTabBadge');
    if (badge) { badge.style.display = n > 0 ? 'inline-block' : 'none'; badge.textContent = label; }
  }
  function recountInbox() {
    var n = 0;
    Object.keys(inboxMap).forEach(function (k) {
      var d = inboxMap[k];
      if (d && d.unread) n += Math.max(1, Number(d.unreadCount) || 0);
    });
    setUnreadBadges(n);
  }
  function threadIsOpen(uid) {
    return currentThreadUid === uid && panel.classList.contains('open') && document.getElementById('tabPrivate').classList.contains('active');
  }
  function markThreadRead(uid) {
    db.ref('inbox/' + myUid + '/' + uid).update({ unread: false, unreadCount: 0 }).catch(function (err) { console.error('inbox mark-read failed:', err); });
  }
  function listenInbox() {
    refs.inbox = db.ref('inbox/' + myUid);
    refs.inbox.on('child_added', function (snap) {
      var data = snap.val() || {};
      inboxMap[snap.key] = data;
      if (inboxReady && data.unread) {
        if (threadIsOpen(snap.key)) { markThreadRead(snap.key); } else { notifyNewMessage(data.otherName); }
      }
      recountInbox();
    });
    refs.inbox.on('child_changed', function (snap) {
      var data = snap.val() || {}, prev = inboxMap[snap.key] || {};
      inboxMap[snap.key] = data;
      if (data.unread && (data.lastTime || 0) > (prev.lastTime || 0)) {
        if (threadIsOpen(snap.key)) { markThreadRead(snap.key); } else { notifyNewMessage(data.otherName); }
      }
      recountInbox();
    });
    refs.inbox.on('child_removed', function (snap) { delete inboxMap[snap.key]; recountInbox(); });
    refs.inbox.once('value').then(function () { inboxReady = true; });
  }

  /* ===== قائمة المحادثات الموجودة بالفعل ===== */
  function loadConvList() {
    currentThreadUid = null;
    document.getElementById('privateThread').style.display = 'none';
    var list = document.getElementById('convList');
    list.style.display = 'flex';
    db.ref('inbox/' + myUid).once('value').then(function (snap) {
      var items = [];
      snap.forEach(function (c) { items.push({ uid: c.key, data: c.val() }); });
      items.sort(function (a, b) { return (b.data.lastTime || 0) - (a.data.lastTime || 0); });
      var html = '';
      items.forEach(function (it) {
        html += '<button class="conv-item' + (it.data.unread ? ' conv-unread' : '') + '" data-uid="' + it.uid + '" data-name="' + escapeHtml(it.data.otherName || '') + '">' +
          '<span class="conv-avatar">👤</span>' +
          '<span class="conv-info"><span class="conv-name">' + escapeHtml(it.data.otherName || '') + (it.data.unread ? '<span class="conv-dot"></span>' : '') + '</span>' +
          '<span class="conv-preview">' + escapeHtml((it.data.lastMessage || '').slice(0, 30)) + '</span></span></button>';
      });
      list.innerHTML = html || '<div class="conv-empty">لا توجد محادثات بعد.<br/>ابدأ من تبويب "المتصلين"</div>';
    }, function (err) { console.error('inbox read failed:', err); });
  }

  /* ===== فتح محادثة خاصة ===== */
  function openPrivateThread(otherUid, otherName) {
    console.log('openPrivateThread called with:', otherUid, otherName);
    document.getElementById('convList').style.display = 'none';
    var thread = document.getElementById('privateThread');
    thread.style.display = 'flex';
    document.getElementById('threadPartnerName').textContent = '👤 ' + otherName;

    var convId = [myUid, otherUid].sort().join('_');

    if (refs.privateMsgs) { refs.privateMsgs.off('value'); }
    var box = document.getElementById('privateMessages');
    box.innerHTML = '';
    refs.privateMsgs = db.ref('chat/private/' + convId).limitToLast(50);
    refs.privateMsgs.on('value', function (snap) {
      var msgs = [];
      snap.forEach(function (c) { msgs.push(c.val()); });
      box.innerHTML = msgs.map(function (m) {
        var mine = m.from === myUid ? ' mine' : '';
        return '<div class="chat-msg' + mine + '"><span class="chat-msg-text">' + escapeHtml(m.text) + '</span></div>';
      }).join('') || '<div class="conv-empty">ابدأ المحادثة الآن ✍️</div>';
      box.scrollTop = box.scrollHeight;
    }, function (err) { console.error('private read failed:', err); });

    currentThreadUid = otherUid;
    markThreadRead(otherUid);

    document.getElementById('privateForm').onsubmit = function (e) {
      e.preventDefault();
      var input = document.getElementById('privateInput');
      var text = input.value.trim();
      if (!text) return;
      db.ref('chat/private/' + convId).push({ from: myUid, fromName: myName, text: text, time: Date.now() });
      db.ref('inbox/' + myUid + '/' + otherUid).update({ otherName: otherName, lastMessage: text, lastTime: Date.now(), unread: false, unreadCount: 0 });
      db.ref('inbox/' + otherUid + '/' + myUid).update({ otherName: myName, lastMessage: text, lastTime: Date.now(), unread: true });
      db.ref('inbox/' + otherUid + '/' + myUid + '/unreadCount').transaction(function (c) { return (Number(c) || 0) + 1; }).catch(function () {});
      input.value = '';
    };
  }

});
