(function () {
  var widget = document.getElementById('featuredSlider');
  if (!widget) return;

  var isHome = window.location.pathname === '/' || window.location.pathname === '';
  if (!isHome) { widget.style.display = 'none'; var fl = document.getElementById('featuredLazy'); if (fl) fl.style.display = 'none'; return; }

  var slidesBox = document.getElementById('featuredSlides');
  var dotsBox = document.getElementById('featuredDots');
  var prevBtn = document.getElementById('featuredPrev');
  var nextBtn = document.getElementById('featuredNext');
  var currentIndex = 0;
  var autoTimer;

  function render(data) {
    var entries = data.feed.entry || [];
    if (!entries.length) {
      slidesBox.setAttribute('aria-busy', 'false');
      widget.style.display = 'none';
      var fl2 = document.getElementById('featuredLazy'); if (fl2) fl2.style.display = 'none';
      return;
    }

    var html = '';
    var dotsHtml = '';
    entries.forEach(function (entry, i) {
      var link = (entry.link || []).find(function (l) { return l.rel === 'alternate'; });
      if (!link) return;
      var title = entry.title.$t;
      var summary = (entry.summary ? entry.summary.$t : (entry.content ? entry.content.$t : '')).replace(/<[^>]+>/g, '').slice(0, 130);

      // استخراج الصورة الذكي (بحث في المصغرات ثم محتوى المقال)
      var image = '';
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        image = entry.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w480-h300-p-k-no-nu-rw/');
      } else if (entry.content && entry.content.$t) {
        var imgMatch = entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (imgMatch && imgMatch[1]) {
          image = imgMatch[1].replace(/\/s[0-9]+(-c)?\//, '/w480-h300-p-k-no-nu-rw/');
        }
      }

      var imageSmall = image.replace('/w480-h300-p-k-no-nu-rw/', '/w320-h200-p-k-no-nu-rw/');
      var imageMedium = image.replace('/w480-h300-p-k-no-nu-rw/', '/w360-h225-p-k-no-nu-rw/');
      var imageRetina = image.replace('/w480-h300-p-k-no-nu-rw/', '/w640-h400-p-k-no-nu-rw/');
      var imageSrcSet = imageRetina !== image ? ' srcset="' + imageSmall + ' 320w, ' + imageMedium + ' 360w, ' + image + ' 480w, ' + imageRetina + ' 640w" sizes="(max-width: 700px) 100vw, 50vw"' : '';

      html += '<div aria-label="المقال المميز ' + (i + 1) + ' من ' + entries.length + '" aria-roledescription="شريحة" class="featured-slide' + (i === 0 ? ' active' : '') + '" role="group">' +
        (image ? '<a class="featured-post-image" href="' + link.href + '"><img src="' + image + '"' + imageSrcSet + ' alt="' + title.replace(/"/g, '&quot;') + '" width="640" height="400" decoding="async" ' + (i === 0 ? 'loading="eager" fetchpriority="high"' : 'loading="lazy" fetchpriority="low"') + '></a>' : '') +
        '<div class="featured-post-body">' +
          '<h2 class="featured-post-title"><a href="' + link.href + '">' + title + '</a></h2>' +
          '<p class="featured-post-snippet">' + summary + '...</p>' +
          '<a class="featured-post-btn" href="' + link.href + '">اقرأ المقال ←</a>' +
        '</div></div>';

      dotsHtml += '<button aria-label="عرض المقال المميز ' + (i + 1) + '" aria-pressed="' + (i === 0 ? 'true' : 'false') + '" class="featured-dot' + (i === 0 ? ' active' : '') + '" data-index="' + i + '" type="button"></button>';
    });

    slidesBox.innerHTML = html;
    dotsBox.innerHTML = dotsHtml;
    slidesBox.setAttribute('aria-busy', 'false');

    var slides = slidesBox.querySelectorAll('.featured-slide');
    var dots = dotsBox.querySelectorAll('.featured-dot');
    var total = slides.length;

    function goTo(index) {
      slides[currentIndex].classList.remove('active');
      dots[currentIndex].classList.remove('active');
      currentIndex = (index + total) % total;
      slides[currentIndex].classList.add('active');
      dots[currentIndex].classList.add('active');
      dots.forEach(function (dot, i) {
        dot.setAttribute('aria-pressed', i === currentIndex ? 'true' : 'false');
      });
    }

    function startAuto() {
      clearInterval(autoTimer);
      if (
        (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) ||
        widget.matches(':hover') ||
        widget.contains(document.activeElement)
      ) return;
      autoTimer = setInterval(function () { goTo(currentIndex + 1); }, 6000);
    }

    dots.forEach(function (dot) {
      dot.addEventListener('click', function () {
        goTo(parseInt(dot.getAttribute('data-index')));
        startAuto();
      });
    });

    prevBtn.addEventListener('click', function () { goTo(currentIndex - 1); startAuto(); });
    nextBtn.addEventListener('click', function () { goTo(currentIndex + 1); startAuto(); });

    widget.addEventListener('mouseenter', function () { clearInterval(autoTimer); });
    widget.addEventListener('mouseleave', startAuto);
    widget.addEventListener('focusin', function () { clearInterval(autoTimer); });
    widget.addEventListener('focusout', function (event) {
      if (!widget.contains(event.relatedTarget)) startAuto();
    });
    startAuto();
  }

  /* التحميل عند الضغط على التاب فقط */
  window.__featuredCb = render;
  window.__lazyInit = window.__lazyInit || {};
  window.__lazyInit.featured = function () {
    var sc = document.createElement('script');
    sc.async = true;
    sc.src = '/feeds/posts/summary/-/' + encodeURIComponent('مميز') + '?alt=json-in-script&max-results=3&callback=__featuredCb';
    sc.onerror = function () {
      slidesBox.setAttribute('aria-busy', 'false');
      slidesBox.innerHTML = '<div class="featured-loading">تعذر تحميل المقالات <button class="lazy-retry" data-retry="featured" type="button">إعادة المحاولة</button></div>';
    };
    document.head.appendChild(sc);
  };
})();
