(function () {
  var TOUR_STEPS = [
    {
      selector: '#colorPickerBtn',
      title: '🎨 غيّر ألوان الموقع',
      text: 'اضغط هنا في أي وقت لتختار اللون اللي يريحك أكتر أثناء القراءة، فيه أكتر من ١٩ لون تقدر تختار من بينهم.',
      position: 'bottom'
    },
    {
      selector: '#chatToggleBtn',
      title: '💬 غرفة المحادثة',
      text: 'من هنا تقدر تدخل غرفة دردشة المجتمع، تتكلم مع باقي القراء أو تبعت رسائل خاصة.',
      position: 'bottom'
    },
    {
      selector: '#notifBellBtn',
      title: '🔔 الإشعارات',
      text: 'تابع من هنا كل جديد وتنبيهات المقالات والردود الخاصة بيك.',
      position: 'bottom'
    },
    {
      selector: '#deepDiveBtn',
      title: '🖥️ وضع القراءة الكامل',
      text: 'اضغط هنا للدخول في وضع ملء الشاشة والتركيز على المحتوى بدون أي تشتيت.',
      position: 'bottom'
    },
    {
      selector: '#categoryBar',
      title: '🗂️ الأقسام والفئات',
      text: 'تصفح المواضيع اللي تهمك من هنا، اختار القسم المفضل عندك بضغطة واحدة.',
      position: 'bottom'
    },
  ];

  var STORAGE_KEY = 'onboardingTourSeen_v1';
  var currentStep = 0;
  var activeSteps = [];

  var overlay = document.getElementById('tourOverlay');
  var spotlight = document.getElementById('tourSpotlight');
  var tooltip = document.getElementById('tourTooltip');
  var titleEl = document.getElementById('tourTitle');
  var textEl = document.getElementById('tourText');
  var dotsEl = document.getElementById('tourDots');
  var nextBtn = document.getElementById('tourNextBtn');
  var skipBtn = document.getElementById('tourSkipBtn');
  var arrowEl = document.getElementById('tourArrow');
  var progressEl = document.getElementById('tourProgress');
  var previousFocus = null;

  function buildDots() {
    dotsEl.innerHTML = '';
    activeSteps.forEach(function (_, i) {
      var d = document.createElement('span');
      d.className = 'tour-dot' + (i === currentStep ? ' active' : '');
      dotsEl.appendChild(d);
    });
  }

  function positionTooltip(rect, position) {
    var tipRect = tooltip.getBoundingClientRect();
    var gap = 16;
    var margin = 12;
    var top, left;

    // حدد الاتجاه المناسب حسب المساحة المتاحة فعلاً
    var spaceBelow = window.innerHeight - rect.bottom;
    var spaceAbove = rect.top;
    var place = position;
    if (place === 'bottom' && spaceBelow < tipRect.height + gap + margin && spaceAbove > spaceBelow) {
      place = 'top';
    } else if (place === 'top' && spaceAbove < tipRect.height + gap + margin && spaceBelow > spaceAbove) {
      place = 'bottom';
    }

    if (place === 'bottom') {
      top = rect.bottom + gap;
      arrowEl.style.top = '-6px';
    } else {
      top = rect.top - tipRect.height - gap;
      arrowEl.style.top = (tipRect.height - 6) + 'px';
    }
    left = rect.left + rect.width / 2 - tipRect.width / 2;

    // إبقاء الكارت جوه حدود الشاشة أفقياً ورأسياً
    if (left < margin) left = margin;
    if (left + tipRect.width > window.innerWidth - margin) {
      left = window.innerWidth - tipRect.width - margin;
    }
    if (top < margin) top = margin;
    if (top + tipRect.height > window.innerHeight - margin) {
      top = window.innerHeight - tipRect.height - margin;
    }

    tooltip.style.top = top + 'px';
    tooltip.style.left = left + 'px';
    arrowEl.style.left = (rect.left + rect.width / 2 - left - 6) + 'px';
  }

  // ينتظر لحد ما التمرير يستقر فعلاً
  function waitForScrollEnd(callback) {
    var lastY = window.scrollY;
    var stableCount = 0;
    var tries = 0;
    var timer = setInterval(function () {
      tries++;
      if (Math.abs(window.scrollY - lastY) < 1) {
        stableCount++;
      } else {
        stableCount = 0;
        lastY = window.scrollY;
      }
      // استقر لـ 3 فحوصات متتالية (~150ms) أو عدّى الحد الأقصى (~1.5 ثانية)
      if (stableCount >= 3 || tries > 30) {
        clearInterval(timer);
        callback();
      }
    }, 50);
  }

  function showStep(index) {
    var step = activeSteps[index];
    var el = document.querySelector(step.selector);
    if (!el) { nextStep(); return; }

    el.scrollIntoView({ behavior: 'smooth', block: 'center' });

    waitForScrollEnd(function () {
      if (!overlay.classList.contains('active')) return;
      var rect = el.getBoundingClientRect();
      var pad = 8;

      spotlight.style.display = 'block';
      spotlight.style.top = (rect.top - pad) + 'px';
      spotlight.style.left = (rect.left - pad) + 'px';
      spotlight.style.width = (rect.width + pad * 2) + 'px';
      spotlight.style.height = (rect.height + pad * 2) + 'px';

      titleEl.textContent = step.title;
      textEl.textContent = step.text;
      tooltip.style.display = 'block';
      tooltip.setAttribute('aria-hidden', 'false');
      progressEl.textContent = 'الخطوة ' + (index + 1) + ' من ' + activeSteps.length;

      requestAnimationFrame(function () {
        positionTooltip(rect, step.position);
        tooltip.classList.add('show');
      });

      buildDots();
      nextBtn.textContent = (index === activeSteps.length - 1) ? 'إنهاء' : 'التالي';
    });
  }

  function nextStep() {
    tooltip.classList.remove('show');
    currentStep++;
    if (currentStep >= activeSteps.length) {
      endTour();
      return;
    }
    setTimeout(function () { showStep(currentStep); }, 200);
  }

  function endTour() {
    overlay.classList.remove('active');
    overlay.setAttribute('aria-hidden', 'true');
    spotlight.style.display = 'none';
    spotlight.setAttribute('aria-hidden', 'true');
    tooltip.style.display = 'none';
    tooltip.setAttribute('aria-hidden', 'true');
    tooltip.classList.remove('show');
    try { localStorage.setItem(STORAGE_KEY, '1'); } catch (e) {}
    // الرجوع لأعلى الصفحة بعد التخطي أو الإنهاء
    window.scrollTo({ top: 0, behavior: 'smooth' });
    if (previousFocus && typeof previousFocus.focus === 'function') previousFocus.focus();
    previousFocus = null;
  }

  function startTour() {
    activeSteps = TOUR_STEPS.filter(function (s) {
      return document.querySelector(s.selector);
    });
    if (!activeSteps.length) return;
    previousFocus = document.activeElement;
    currentStep = 0;
    overlay.classList.add('active');
    overlay.setAttribute('aria-hidden', 'false');
    spotlight.setAttribute('aria-hidden', 'false');
    showStep(0);
    skipBtn.focus();
  }

  nextBtn.addEventListener('click', nextStep);
  skipBtn.addEventListener('click', endTour);
  document.addEventListener('keydown', function (event) {
    if (!overlay.classList.contains('active')) return;
    if (event.key === 'Escape') {
      event.preventDefault();
      endTour();
      return;
    }
    if (event.key === 'Tab') {
      if (event.shiftKey && document.activeElement === skipBtn) {
        event.preventDefault();
        nextBtn.focus();
      } else if (!event.shiftKey && document.activeElement === nextBtn) {
        event.preventDefault();
        skipBtn.focus();
      } else if (!tooltip.contains(document.activeElement)) {
        event.preventDefault();
        skipBtn.focus();
      }
    }
  });

  window.addEventListener('resize', function () {
    if (overlay.classList.contains('active') && activeSteps[currentStep]) {
      showStep(currentStep);
    }
  });

  document.addEventListener('DOMContentLoaded', function () {
    var seen = false;
    try { seen = !!localStorage.getItem(STORAGE_KEY); } catch (e) {}
    if (!seen) {
      onFirstInteraction(function () { setTimeout(startTour, 1500); }, 12000);
    }
  });

  // للاختبار اليدوي من الكونسول: restartOnboardingTour()
  window.restartOnboardingTour = function () {
    try { localStorage.removeItem(STORAGE_KEY); } catch (e) {}
    startTour();
  };
})();
