document.addEventListener('DOMContentLoaded', function () {
  const categoryBar = document.getElementById('categoryBar');
  const scrollRightBtn = document.getElementById('catScrollRight');
  const scrollLeftBtn = document.getElementById('catScrollLeft');

  if (!categoryBar) return;

  // 1. أزرار الأسهم والتمرير
  const scrollAmount = 250;
  if (scrollRightBtn) {
    scrollRightBtn.addEventListener('click', function (e) {
      e.preventDefault();
      categoryBar.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });
  }

  if (scrollLeftBtn) {
    scrollLeftBtn.addEventListener('click', function (e) {
      e.preventDefault();
      categoryBar.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    });
  }

  // 2. ترتيب الفئات حسب عدد المقالات (Descending)
  const pills = Array.from(categoryBar.querySelectorAll('.cat-pill:not(.cat-home)'));
  pills.sort((a, b) => {
    const countA = parseInt(a.getAttribute('data-count') || '0', 10);
    const countB = parseInt(b.getAttribute('data-count') || '0', 10);
    return countB - countA;
  });
  pills.forEach(pill => categoryBar.appendChild(pill));

  // 3. تحديد الفئة النشطة (سواء في صفحة القسم أو داخل مقال معين)
  const currentUrl = window.location.href.split('?')[0].split('#')[0];
  let activePill = null;

  // أ) التحقق لو نحن في صفحة فئة مباشرة
  pills.forEach(pill => {
    if (pill.href && pill.href.split('?')[0].split('#')[0] === currentUrl) {
      activePill = pill;
    }
  });

  // ب) التحقق لو نحن داخل صفحة مقال مفتوح (من خلال window.currentPostLabels)
  if (!activePill && window.currentPostLabels && window.currentPostLabels.length > 0) {
    pills.forEach(pill => {
      const pillLabel = pill.getAttribute('data-label');
      if (pillLabel && window.currentPostLabels.includes(pillLabel)) {
        activePill = pill; // يحدد أول فئة ينتمي إليها المقال
      }
    });
  }

  // ج) إعطاء الكلاس وتحديد التمرير التلقائي للقسم المفتوح
  if (activePill) {
    const homePill = categoryBar.querySelector('.cat-home');
    if (homePill) homePill.classList.remove('active');

    activePill.classList.add('active');

    // تمرير الشريط تلقائياً ليكون القسم المفتوح ممركزاً وواضحاً
    setTimeout(() => {
      const pillOffset = activePill.offsetLeft - (categoryBar.clientWidth / 2) + (activePill.clientWidth / 2);
      categoryBar.scrollTo({ left: pillOffset, behavior: 'smooth' });
    }, 250);
  }
});
