/* COLOR SWATCH PICKER ENGINE - UPDATED & FIXED */
const THEME_COLORS = [
  { value: '#475569', name: 'سليت رمادي' },
  { value: '#0D9488', name: 'تركواز حيوي' },
  { value: '#4F46E5', name: 'نيلي ملكي' },
  { value: '#C08A2E', name: 'ذهبي فخم' },
  { value: '#A31545', name: 'كريمزون نبيتي' },
  { value: '#276749', name: 'أخضر غامق' },
  { value: '#3D6B96', name: 'أزرق ستيل' },
  { value: '#2563EB', name: 'أزرق ياقوتي' },
  { value: '#6B4C7A', name: 'باذنجاني هادئ' },
  { value: '#0E7490', name: 'سماوي بترولي' },
  { value: '#E07B39', name: 'برتقالي دافئ' },
  { value: '#D9548A', name: 'بينك هادئ' },
  { value: '#5C7A29', name: 'زيتوني أخضر' },
  { value: '#8B9DC3', name: 'لبني فاتح' },
  { value: '#EF5350', name: 'أحمر حيوي' },
  { value: '#FACC15', name: 'أصفر عباد شمس' },
  { value: '#14C38E', name: 'أخضر نعناعي' },
  { value: '#F0668C', name: 'كورال وردي' },
  { value: '#C458D6', name: 'فوشيا أوركيد' },
  { value: '#111827', name: 'وضع ليلي' }
];

function initColorPicker() {
  const pickerBtn = document.getElementById('colorPickerBtn');
  const panel = document.getElementById('colorPickerPanel');
  const grid = document.getElementById('colorSwatchGrid');
  const currentSwatch = document.getElementById('colorSwatchCurrent');
  if (!pickerBtn || !grid) return;

  let html = '';
  THEME_COLORS.forEach((c) => {
    const isNight = c.value === '#111827';
    const nightStyle = isNight ? 'border:1px solid #4b5563;' : '';
    const nightIcon = isNight
      ? '<svg class="night-icon" width="14" height="14" viewBox="0 0 24 24" style="display:block;pointer-events:none;"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z" fill="#facc15"/></svg>'
      : '';
    html += `<button aria-label="${c.name}" class="color-swatch-item${isNight ? ' color-swatch-night' : ''}" data-color="${c.value}" style="background:${c.value};${nightStyle}display:flex;align-items:center;justify-content:center;" type="button" title="${c.name}">${nightIcon}</button>`;
  });
  grid.innerHTML = html;

  function applyColor(color) {
    // 1. تحديث خاصية data-theme على body
    document.body.setAttribute('data-theme', color);

    // 2. تغيير متغيرات الـ CSS الرئيسية ديناميكياً ليتم تطبيق اللون فوراً على الموقع
    document.documentElement.style.setProperty('--primary', color);

    // 3. التعامل مع الوضع الليلي بشكل خاص إذا اختار المستخدم #111827
    if (color === '#111827') {
      document.body.classList.add('dark-theme');
    } else {
      document.body.classList.remove('dark-theme');
    }

    // 4. تحديث شكل العينة المختارة والحفظ
    if (currentSwatch) currentSwatch.style.background = color;
    localStorage.setItem('selectedBlogTheme', color);

    // 5. تحديد الزر النشط داخل القائمة
    grid.querySelectorAll('.color-swatch-item').forEach((el) => {
      el.classList.toggle('selected', el.getAttribute('data-color') === color);
    });
  }

  // تطبيق اللون المحفوظ فور فتح الصفحة
  const savedColor = localStorage.getItem('selectedBlogTheme') || '#475569';
  applyColor(savedColor);

  // إضافة أحداث الضغط على الأزرار
  grid.querySelectorAll('.color-swatch-item').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      const selectedColor = btn.getAttribute('data-color');
      applyColor(selectedColor);
      if (panel) panel.classList.remove('open');
    });
  });

  pickerBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if (panel) panel.classList.toggle('open');
  });

  document.addEventListener('click', (e) => {
    if (panel && !panel.contains(e.target) && e.target !== pickerBtn) {
      panel.classList.remove('open');
    }
  });
}

document.addEventListener('DOMContentLoaded', () => {
  initColorPicker();
  if (typeof initProgressBar === 'function') {
    initProgressBar();
  }
});
