document.addEventListener("DOMContentLoaded", function() {
  var container = document.getElementById("numberedPagination");
  var numContainer = document.getElementById("paginationNumbers");
  var olderBtn = document.getElementById("blog-pager-older-link");
  var newerBtn = document.getElementById("blog-pager-newer-link");

  if (!numContainer) return;

  var currentUrl = window.location.href;

  // تحديد رقم الصفحة الحالية تلقائياً من الـ URL
  var currentPage = 1;
  var pageMatch = currentUrl.match(/page=(\d+)/);
  if (pageMatch) {
    currentPage = parseInt(pageMatch[1]);
  } else if (currentUrl.indexOf("updated-max") !== -1 || currentUrl.indexOf("archive") !== -1) {
    // إذا كان الرابط يحتوي على معلمات التصفح ولكن ليس به رقم صفحة صريح
    currentPage = 2;
  }

  // تنظيف الحاوية
  numContainer.innerHTML = "";

  // 1. زر الصفحة الأولى دائماً
  if (currentPage > 1) {
    var homeBtn = document.createElement("a");
    homeBtn.className = "page-num";
    homeBtn.textContent = "1";
    homeBtn.href = window.location.pathname;
    numContainer.appendChild(homeBtn);

    if (currentPage > 2) {
      var dots1 = document.createElement("span");
      dots1.className = "page-dots";
      dots1.textContent = "...";
      numContainer.appendChild(dots1);
    }
  }

  // 2. رقم الصفحة الحالية النشطة
  var activeBtn = document.createElement("span");
  activeBtn.className = "page-num active";
  activeBtn.textContent = currentPage;
  numContainer.appendChild(activeBtn);

  // 3. زر الصفحة التالية إذا كانت متوفرة
  if (olderBtn && olderBtn.tagName === 'A' && olderBtn.getAttribute('href')) {
    var nextUrl = olderBtn.getAttribute('href');

    // إضافة معلمة الصفحة لتمييزها
    if (nextUrl.indexOf("page=") === -1) {
      var sep = nextUrl.indexOf("?") !== -1 ? "&" : "?";
      nextUrl = nextUrl + sep + "page=" + (currentPage + 1);
    }

    var nextNumBtn = document.createElement("a");
    nextNumBtn.className = "page-num";
    nextNumBtn.textContent = currentPage + 1;
    nextNumBtn.href = nextUrl;
    numContainer.appendChild(nextNumBtn);

    // تحديث رابط زر "التالي" الرئيسي ليعمل بدقة
    olderBtn.setAttribute('href', nextUrl);
  }

  // تحديث رابط زر "السابق" الرئيسي في حالة العودة للرئيسية
  if (newerBtn && newerBtn.tagName === 'A' && currentPage === 2) {
    newerBtn.setAttribute('href', window.location.pathname);
  }
});
