let o=document.createElement("div");
o.className="h1-orbit";
o.innerHTML='<svg aria-hidden="true" viewBox="0 0 200 200"><circle class="h1-moon" cx="100" cy="100" r="45"/><circle class="h1-ring" cx="100" cy="100" r="70"/><circle class="h1-star h1-s1" cx="40" cy="40" r="2"/><circle class="h1-star h1-s2" cx="160" cy="50" r="2"/><circle class="h1-star h1-s3" cx="50" cy="160" r="2"/><circle class="h1-star h1-s4" cx="165" cy="155" r="2"/></svg>';
h.append(o);
});
}catch(e){console.error("H1:",e)}

/* ===== TEST ===== */
(function(){

function initTests(){

document.querySelectorAll("#postBody test").forEach(function(test){

var qs=Array.prototype.filter.call(test.children,function(x){
return /^test\d+$/i.test(x.tagName.toLowerCase());
});

if(!qs.length)return;

var answers=[
["نعم",3],
["غالبًا",2],
["لست متأكدًا",1],
["لا",0]
];

var current=0;
var scores=[];

/* تجهيز الأسئلة */
qs.forEach(function(q,i){

var title=q.textContent.trim();
q.textContent="";
q.setAttribute("data-index",i);

var text=document.createElement("div");
text.textContent=title;
q.appendChild(text);

answers.forEach(function(a){

var label=document.createElement("label");
var input=document.createElement("input");

input.type="radio";
input.name="magtest"+i;
input.value=a[1];

label.appendChild(input);
label.appendChild(document.createTextNode(a[0]));

q.appendChild(label);

label.addEventListener("click",function(){

q.querySelectorAll("label").forEach(function(x){
x.classList.remove("selected");
});

label.classList.add("selected");

});

});

});

/* النتائج */
var plusEl=test.querySelector("resultplus");
var minusEl=test.querySelector("resultminus");

var plus=plusEl?plusEl.innerHTML:"";
var minus=minusEl?minusEl.innerHTML:"";

/* حذف النتائج الأصلية */
if(plusEl)plusEl.remove();
if(minusEl)minusEl.remove();

/* زر التالي */
var next=document.createElement("button");
next.type="button";
next.className="test-next";
next.textContent="التالي ←";

/* صندوق النتيجة */
var resultBox=document.createElement("testresult");
resultBox.className="test-result-box";

test.appendChild(next);
test.appendChild(resultBox);

/* عرض سؤال واحد */
function showQuestion(index){

qs.forEach(function(q,i){

if(i===index){
q.classList.add("test-current");
}else{
q.classList.remove("test-current");
}

});

next.textContent=
index===qs.length-1
?"اعرض النتيجة"
:"التالي ←";

}

/* البداية */
showQuestion(0);

/* التالي */
next.addEventListener("click",function(){

var q=qs[current];
var selected=q.querySelector("input:checked");

if(!selected){

q.classList.add("test-error");

setTimeout(function(){
q.classList.remove("test-error");
},500);

return;
}

scores[current]=Number(selected.value);

if(current<qs.length-1){

current++;

showQuestion(current);

}else{

var score=0;

scores.forEach(function(v){
score+=v;
});

var max=qs.length*3;
var percent=Math.round(score/max*100);

resultBox.innerHTML=percent>=50?plus:minus;
resultBox.classList.add("show");

next.style.display="none";

resultBox.scrollIntoView({
behavior:"smooth",
block:"center"
});

}

});

});

}

if(document.readyState==="loading"){
document.addEventListener("DOMContentLoaded",initTests);
}else{
initTests();
}

})();

/* ===== CHART ===== */
try{
document.querySelectorAll("#postBody chart").forEach(c=>{

let title=(c.querySelector("title")||{}).textContent||"";
title=title.trim();

let unit=c.getAttribute("unit")||"%";

let bars=[...c.querySelectorAll("bar")].map(b=>({
label:(b.querySelector("label")||{}).textContent||"",
value:Math.max(0,parseFloat((b.querySelector("value")||{}).textContent)||0)
}));

if(!bars.length)return;

bars.forEach(b=>b.label=b.label.trim());

let wrap=document.createElement("div"),
canvas=document.createElement("canvas"),
tip=document.createElement("div");

wrap.className="chart-canvas-wrap";
canvas.className="chart-canvas";
tip.className="chart-tooltip";

canvas.setAttribute("role","img");
canvas.setAttribute("aria-label",title);
tip.setAttribute("role","tooltip");
tip.style.display="none";

wrap.append(canvas,tip);
c.innerHTML="";
c.append(wrap);

let active=-1,
barAreas=[];

function hideTip(){
tip.style.display="none";
active=-1;
}

function showTip(i){
let b=bars[i],a=barAreas[i];
if(!a)return;

active=i;

tip.innerHTML=
"<strong>"+b.label+"</strong>"+
"<span>"+(unit==="%"?b.value+"%":b.value+" "+unit)+"</span>";

tip.style.display="block";

let tw=tip.offsetWidth,
th=tip.offsetHeight,
left=a.cx-tw/2,
top=a.y-th-12;

if(left<6)left=6;
if(left+tw>wrap.clientWidth-6)
left=wrap.clientWidth-tw-6;

if(top<6)top=a.y+a.h+12;

tip.style.left=left+"px";
tip.style.top=top+"px";
}

function draw(){

let d=window.devicePixelRatio||1,
w=wrap.clientWidth,
h=window.innerWidth<=600?320:360;

if(!w)return;

canvas.width=w*d;
canvas.height=h*d;
canvas.style.width=w+"px";
canvas.style.height=h+"px";

let x=canvas.getContext("2d");

x.setTransform(d,0,0,d,0,0);
x.clearRect(0,0,w,h);

let cs=getComputedStyle(c),
root=getComputedStyle(document.documentElement),

primary=cs.getPropertyValue("--primary").trim()||
root.getPropertyValue("--primary").trim(),

muted=cs.getPropertyValue("--text-muted").trim()||
root.getPropertyValue("--text-muted").trim(),

border=cs.getPropertyValue("--card-border").trim()||
root.getPropertyValue("--card-border").trim(),

main=cs.getPropertyValue("--text-main").trim()||
root.getPropertyValue("--text-main").trim(),

f=cs.fontFamily||"Arial";

let many=bars.length>6;

let L=48,R=18,T=48,B=many?105:82,
cw=w-L-R,
ch=h-T-B;

let max=unit==="%"?100:Math.max(...bars.map(b=>b.value));

if(!isFinite(max)||max<=0)max=100;

if(unit!=="%"){
let step=Math.pow(10,Math.floor(Math.log10(max)));
max=Math.ceil(max/step)*step;
if(max<100)max=Math.ceil(max/10)*10;
}

/* العنوان */
x.fillStyle=main;
x.font="800 15px "+f;
x.textAlign="center";
x.textBaseline="top";
x.fillText(title,w/2,8);

/* الشبكة */
for(let i=0;i<=4;i++){

let v=max-i*(max/4),
y=T+ch*i/4;

x.strokeStyle=border;
x.lineWidth=1;
x.setLineDash([3,4]);
x.beginPath();
x.moveTo(L,y);
x.lineTo(w-R,y);
x.stroke();
x.setLineDash([]);

x.fillStyle=muted;
x.font="700 11px "+f;
x.textAlign="right";
x.textBaseline="middle";

x.fillText(
unit==="%"?Math.round(v)+"%":Math.round(v)+" "+unit,
L-9,y
);
}

/* المحاور */
x.strokeStyle=border;
x.lineWidth=1;
x.beginPath();
x.moveTo(L,T);
x.lineTo(L,T+ch);
x.lineTo(w-R,T+ch);
x.stroke();

let gap=cw/(bars.length+1),
barW=Math.min(60,gap*.42);

barAreas=[];

bars.forEach((b,i)=>{

let cx=L+gap*(i+1),
bh=ch*b.value/max,
y=T+ch-bh;

barAreas.push({
x:cx-barW/2-8,
y:y-8,
w:barW+16,
h:bh+16,
cx:cx
});

/* العمود */
x.fillStyle=primary;
x.beginPath();

if(x.roundRect){
x.roundRect(cx-barW/2,y,barW,bh,6);
}else{
x.rect(cx-barW/2,y,barW,bh);
}

x.fill();

/* القيمة */
x.fillStyle=primary;
x.font="900 12px "+f;
x.textAlign="center";
x.textBaseline="bottom";

if(many){

x.save();
x.translate(cx,y-8);
x.rotate(-Math.PI/2);
x.textAlign="left";
x.textBaseline="middle";

x.fillText(
unit==="%"?b.value+"%":b.value+" "+unit,
0,0
);

x.restore();

}else{

x.fillText(
unit==="%"?b.value+"%":b.value+" "+unit,
cx,y-7
);

}

/* اسم العنصر */
x.fillStyle=muted;
x.font="700 11px "+f;

if(many){

x.save();
x.translate(cx,T+ch+16);
x.rotate(-Math.PI/2);
x.textAlign="right";
x.textBaseline="middle";
x.fillText(b.label,0,0);
x.restore();

}else{

x.textAlign="center";
x.textBaseline="top";

let words=b.label.split(/\s+/),
lines=[],
line="";

words.forEach(word=>{
let test=line?line+" "+word:word;

if(x.measureText(test).width>110&&line){
lines.push(line);
line=word;
}else{
line=test;
}
});

if(line)lines.push(line);

lines.forEach((line,j)=>{
x.fillText(line,cx,T+ch+20+j*17);
});

}

});

if(active>=0)showTip(active);
}

/* تحديد العمود */
function getBar(e){

let r=canvas.getBoundingClientRect(),
px=e.clientX-r.left,
py=e.clientY-r.top;

for(let i=0;i<barAreas.length;i++){

let a=barAreas[i];

if(
px>=a.x&&
px<=a.x+a.w&&
py>=a.y&&
py<=a.y+a.h
)return i;

}

return -1;
}

/* الكمبيوتر: Hover */
canvas.addEventListener("pointermove",function(e){

if(e.pointerType==="touch")return;

let i=getBar(e);

if(i>=0){
showTip(i);
canvas.style.cursor="pointer";
}else{
hideTip();
canvas.style.cursor="default";
}

});

/* الكمبيوتر + الموبايل */
canvas.addEventListener("pointerup",function(e){

let i=getBar(e);

if(i<0){
hideTip();
return;
}

if(e.pointerType==="touch"){

if(active===i){
hideTip();
}else{
showTip(i);
}

}else{

showTip(i);

}

});

/* خروج الماوس */
canvas.addEventListener("pointerleave",function(e){

if(e.pointerType!=="touch"){
hideTip();
canvas.style.cursor="default";
}

});

/* لمس خارج التشارت */
document.addEventListener("pointerup",function(e){

if(
e.pointerType==="touch"&&
!wrap.contains(e.target)
){
hideTip();
}

});

if("ResizeObserver" in window){
new ResizeObserver(draw).observe(wrap);
}

draw();

new MutationObserver(draw).observe(document.documentElement,{
attributes:true,
attributeFilter:["style","class"]
});

new MutationObserver(draw).observe(document.body,{
attributes:true,
attributeFilter:["style","class"]
});

});
}catch(e){console.error("CHART:",e)}

/* ===== STATS ===== */
try{

document.querySelectorAll("#postBody stat").forEach(s=>{

let n=s.querySelector("num");
if(!n)return;

let v=parseFloat(n.textContent)||0,
circ=2*Math.PI*54;

n.insertAdjacentHTML(
"afterbegin",
'<svg viewBox="0 0 120 120" aria-hidden="true"><circle class="ring-bg" cx="60" cy="60" r="54"/><circle class="ring-fill" cx="60" cy="60" r="54"/></svg>'
);

n.style.setProperty("--offset",circ*(1-v/100));
});

if("IntersectionObserver" in window){

let io=new IntersectionObserver(es=>{
es.forEach(e=>{
if(e.isIntersecting){
e.target.classList.add("active","pulse");
io.unobserve(e.target);
}
});
},{threshold:.45});

document.querySelectorAll("#postBody stat").forEach(s=>io.observe(s));

}else{

document.querySelectorAll("#postBody stat")
.forEach(s=>s.classList.add("active","pulse"));

}

}catch(e){console.error("STATS:",e)}

});

/* ===== progressx ===== */
document.addEventListener("DOMContentLoaded",function(){
  document.querySelectorAll("#postBody progressx").forEach(function(el){
    if(!("IntersectionObserver" in window)){
      el.classList.add("is-visible");
      return;
    }

    new IntersectionObserver(function(entries,observer){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          el.classList.add("is-visible");
          observer.unobserve(el);
        }
      });
    },{
      threshold:.35
    }).observe(el);
  });
});
