body.script:
//
(function () {
  var widget = document.getElementById('followersWidget');
  var mount = document.getElementById('followers-iframe-container');
  var button = document.getElementById('loadFollowersButton');
  var status = document.getElementById('followersLoading');
  if (!widget || !mount || !button || !status) return;

  var platformPromise = null;
  var requestStarted = false;
  var loaded = false;
  var loadTimer = null;
  var colors = 'Cgt0cmFuc3BhcmVudBILdHJhbnNwYXJlbnQaByMwMDAwMDAiByMwMDAwMDAqByNGRkZGRkYyByMwMDAwMDA6ByMwMDAwMDBKByMwMDAwMDBSByNGRkZGRkZaC3RyYW5zcGFyZW50';
  var blogId = mount.getAttribute('data-blog-id');
  var frameUrl = 'https://www.blogger.com/followers/frame/' +
    encodeURIComponent(blogId || '') +
    '?colors=' + encodeURIComponent(colors) +
    '&pageSize=21&hl=ar&origin=' + encodeURIComponent(window.location.origin);

  function labelFrame(frame) {
    if (!frame || frame.tagName !== 'IFRAME') return;
    frame.setAttribute('title', 'متابعو المدونة');
  }

  function labelFrames(root) {
    if (!root) return;
    if (root.tagName === 'IFRAME') labelFrame(root);
    if (root.querySelectorAll) {
      Array.prototype.forEach.call(root.querySelectorAll('iframe'), labelFrame);
    }
  }

  if ('MutationObserver' in window) {
    new MutationObserver(function (records) {
      records.forEach(function (record) {
        Array.prototype.forEach.call(record.addedNodes, labelFrames);
      });
    }).observe(mount, { childList: true, subtree: true });
  }

  function showError() {
    requestStarted = false;
    button.disabled = false;
    widget.setAttribute('aria-busy', 'false');
    status.textContent = 'تعذر تحميل أداة المتابعين. حاول مرة أخرى.';
    if (loadTimer) window.clearTimeout(loadTimer);
  }

  function ensurePlatform() {
    if (window.gapi && typeof window.gapi.load === 'function') {
      return Promise.resolve();
    }
    if (platformPromise) return platformPromise;
    platformPromise = new Promise(function (resolve, reject) {
      var script = document.createElement('script');
      script.src = 'https://apis.google.com/js/platform.js';
      script.async = true;
      script.onload = function () {
        if (window.gapi && typeof window.gapi.load === 'function') resolve();
        else {
          platformPromise = null;
          reject(new Error('Google API unavailable'));
        }
      };
      script.onerror = function () {
        platformPromise = null;
        reject(new Error('Google API failed to load'));
      };
      document.head.appendChild(script);
    });
    return platformPromise;
  }

  function openFollowersFrame(url) {
    var api = window.gapi && window.gapi.iframes;
    if (!api || !api.getContext) {
      showError();
      return;
    }
    var child;
    try {
      child = api.getContext().openChild({
        url: url,
        where: mount,
        messageHandlersFilter: api.CROSS_ORIGIN_IFRAMES_FILTER,
        messageHandlers: {
          '_ready': function (data) {
            var frame = child && child.getIframeEl();
            labelFrame(frame);
            if (frame && data && Number(data.height) > 0) frame.height = Number(data.height);
            loaded = true;
            requestStarted = false;
            var subOk = button.querySelector('.lazy-sub'); if (subOk) subOk.textContent = 'تم تحميل القائمة ✓';
            widget.setAttribute('aria-busy', 'false');
            status.textContent = 'تم تحميل أداة المتابعين.';
            if (loadTimer) window.clearTimeout(loadTimer);
          },
          'reset': function () {
            if (child) child.close();
            openFollowersFrame(frameUrl);
          },
          'open': function (nextUrl) {
            if (child) child.close();
            openFollowersFrame(nextUrl);
          }
        }
      });
      window.followersIframe = child;
      labelFrames(mount);
    } catch (error) {
      showError();
    }
  }

  button.addEventListener('click', function () {
    if (requestStarted || loaded) return;
    requestStarted = true;
    widget.setAttribute('aria-busy', 'true');
    status.textContent = 'جاري تحميل أداة المتابعين...';
    loadTimer = window.setTimeout(showError, 20000);
    ensurePlatform().then(function () {
      try {
        window.gapi.load('gapi.iframes', function () {
          openFollowersFrame(frameUrl);
        });
      } catch (error) {
        showError();
      }
    }).catch(showError);
  });
})();
