(function () {
  var init = window.__lazyInit = window.__lazyInit || {}, done = {};
  function run(name) {
    var f = init[name];
    if (done[name] || typeof f !== 'function') return;
    done[name] = true;
    try { f(); } catch (e) { done[name] = false; }
  }
  document.addEventListener('click', function (e) {
    var t = e.target;
    if (!t || !t.closest) return;
    var r = t.closest('.lazy-retry');
    if (r) { var n = r.getAttribute('data-retry'); done[n] = false; run(n); return; }
    var b = t.closest('.lazy-tab[data-lazy]');
    if (!b) return;
    var w = b.closest('.lazy-widget');
    if (!w) return;
    var open = w.classList.toggle('is-open');
    b.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) run(b.getAttribute('data-lazy'));
  });
})();
