/* تسريع التنقل: تحميل مسبق ذكي للصفحة قبل الضغط عليها */
(function () {
  var c = navigator.connection || {};
  if (c.saveData || /2g/.test(c.effectiveType || '')) return;
  function go() {
    try {
      if (window.HTMLScriptElement && HTMLScriptElement.supports && HTMLScriptElement.supports('speculationrules')) {
        var s = document.createElement('script');
        s.type = 'speculationrules';
        s.textContent = JSON.stringify({ prefetch: [{ where: { and: [{ href_matches: '/*' }, { not: { href_matches: ['/search*', '/b/*', '/feeds/*', '/*#*'] } }] }, eagerness: 'moderate' }] });
        document.head.appendChild(s);
        return;
      }
    } catch (e) {}
    var done = {}, timer;
    function pf(a) {
      if (!a || !a.href || a.origin !== location.origin || a.target === '_blank' || a.hash || done[a.href] || /^\/(search|feeds|b)(\/|$)/.test(a.pathname)) return;
      done[a.href] = 1;
      var l = document.createElement('link');
      l.rel = 'prefetch'; l.href = a.href;
      document.head.appendChild(l);
    }
    document.addEventListener('touchstart', function (e) { pf(e.target.closest && e.target.closest('a')); }, { passive: true, capture: true });
    document.addEventListener('mouseover', function (e) {
      var a = e.target.closest && e.target.closest('a');
      if (!a) return;
      clearTimeout(timer);
      timer = setTimeout(function () { pf(a); }, 80);
    }, { passive: true, capture: true });
  }
  if (typeof onFirstInteraction === 'function') onFirstInteraction(go, 6000);
  else window.addEventListener('load', function () { setTimeout(go, 1500); });
})();
