b:if.script:
//
/* ===== بحث مخصص: يفكك الجملة لكلمات، يتجاهل حروف الجر والـ "ال" وحروف العلة، ويجمع النتائج ===== */
(function () {
  var root = document.documentElement;
  if (!root.classList.contains('cs-on')) return;
  var Q = (new URLSearchParams(location.search).get('q') || '').trim();
  var main = document.getElementById('main-content');
  if (!Q || !main) { root.classList.remove('cs-on'); return; }

  function esc(s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function norm(s) {
    return String(s || '').toLowerCase()
      .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
      .replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ؤ/g, 'و').replace(/ئ/g, 'ي')
      .replace(/ة/g, 'ه')
      .replace(/[^\u0621-\u064Aa-z0-9\u0660-\u0669\s]/g, ' ');
  }
  var STOP_RAW = 'في من الى إلى على عن مع عند عنده ثم او أو ام هل ما ماذا لماذا كيف متى اين هذا هذه هذي ذلك تلك هو هي هم انا انت نحن لو التي الذي اللي الذين كان كانت يكون كل قد لا لم لن ان إن أن انه انها بعد قبل بين خلال حول ضد حتى منذ دون غير فقط جدا ايه ازاي عايز عايزه عاوز عاوزه اريد أريد ابغى ابي محتاج محتاجه ممكن مقال مقالات مقاله موضوع مواضيع معلومات معلومه اكتب ابحث بحث دلني يا بس كمان برضو اي ايضا يعني زي مثل علشان عشان لان لأن لكن بل اذا إذا اما أما الا إلا سوى عنها عنه منها منه فيه فيها به بها له لها لهم عليه عليها اليه اليها معه معها هناك هنا ده دي دا ديه دول لي لك لنا انتم تفيد يفيد فايده فوايد ضروري';
  var STOP = {};
  norm(STOP_RAW).split(/\s+/).forEach(function (w) { if (w) STOP[w] = 1; });

  function skel(w) {
    var o = w;
    w = w.replace(/^(?:وال|فال|بال|كال|لل|ال)/, '');
    if (w.length < 2) w = o;
    for (var n = 0; n < 2 && w.length > 4; n++) w = w.replace(/(?:ات|ون|ين|ان|ها|هم|كم|نا)$/, '');
    if (w.length > 3) w = w.replace(/ه$/, '');
    return w.charAt(0) + w.slice(1).replace(/[اويى]/g, '');
  }
  function words(s) { return norm(s).split(/\s+/).filter(Boolean); }
  function toks(s, keepStop) {
    var out = [];
    words(s).forEach(function (w) {
      if (!keepStop && STOP[w]) return;
      var k = skel(w);
      if (k.length >= 2) out.push(k);
    });
    return out;
  }
  function hit(t, set) {
    for (var i = 0; i < set.length; i++) {
      var w = set[i];
      if (t.length >= 4) { if (w.indexOf(t) > -1 || (w.length >= 4 && t.indexOf(w) > -1)) return true; }
      else if (w === t || w.indexOf(t) === 0) return true;
    }
    return false;
  }

  var qt = toks(Q);
  var ignored = words(Q).filter(function (w) { return STOP[w]; });
  if (!qt.length) qt = toks(Q, true);
  var uniq = []; qt.forEach(function (t) { if (uniq.indexOf(t) < 0) uniq.push(t); }); qt = uniq;

  var qWords = words(Q).filter(function (w) { return !STOP[w]; });
  var box = document.createElement('section');
  box.className = 'cs-results'; box.id = 'csResults';
  box.innerHTML = '<div class="cs-head"><h1 class="cs-title">نتائج البحث</h1>' +
    '<form action="/search" class="cs-form" method="get"><input aria-label="ابحث" class="cs-input" name="q" type="search" value="' + esc(Q) + '"/><button class="cs-go" type="submit">بحث</button></form>' +
    '<div class="cs-chips" id="csChips"></div><div class="cs-count" id="csCount"><span class="lazy-spin"></span> جاري البحث...</div></div><div class="cs-list" id="csList"></div>';
  main.insertBefore(box, main.firstChild);

  var chips = '';
  qWords.forEach(function (w) { chips += '<span class="cs-chip">' + esc(w) + '</span>'; });
  ignored.forEach(function (w) { chips += '<span class="cs-chip cs-chip-off" title="كلمة تم تجاهلها">' + esc(w) + '</span>'; });
  document.getElementById('csChips').innerHTML = chips;

  function fail() { root.classList.remove('cs-on'); if (box.parentNode) box.parentNode.removeChild(box); }

  var KEY = 'cs_idx_v1', TTL = 6 * 3600 * 1000;
  function load() {
    return new Promise(function (res, rej) {
      try {
        var c = JSON.parse(localStorage.getItem(KEY) || 'null');
        if (c && c.d && c.d.length && Date.now() - c.t < TTL) { res(c.d); return; }
      } catch (e) {}
      var all = [], start = 1, N = 150;
      (function next() {
        fetch('/feeds/posts/summary?alt=json&max-results=' + N + '&start-index=' + start, { credentials: 'omit' })
          .then(function (r) { if (!r.ok) throw new Error('feed'); return r.json(); })
          .then(function (j) {
            var es = (j.feed && j.feed.entry) || [];
            es.forEach(function (e) {
              var link = '';
              (e.link || []).forEach(function (l) { if (l.rel === 'alternate') link = l.href; });
              if (!link) return;
              all.push({
                t: (e.title && e.title.$t) || '',
                u: link,
                s: ((e.summary && e.summary.$t) || '').replace(/\s+/g, ' ').slice(0, 500),
                l: (e.category || []).map(function (c) { return c.term; }),
                i: (e.media$thumbnail && e.media$thumbnail.url) || '',
                d: (e.published && e.published.$t) || ''
              });
            });
            if (es.length === N && start < 1500) { start += N; next(); }
            else { try { localStorage.setItem(KEY, JSON.stringify({ t: Date.now(), d: all })); } catch (e) {} res(all); }
          }).catch(rej);
      })();
    });
  }

  function hl(text) {
    return String(text).split(/([\u0600-\u06FF]+)/).map(function (p, i) {
      if (i % 2 === 0) return esc(p);
      var w = norm(p).trim();
      if (!w || STOP[w]) return esc(p);
      var k = skel(w);
      return k.length >= 2 && qt.some(function (t) { return hit(t, [k]); }) ? '<mark>' + esc(p) + '</mark>' : esc(p);
    }).join('');
  }
  function thumb(u) {
    if (!u) return '';
    var r = u.replace(/\/s\d+(-c)?\//, '/w240-h170-p-k-no-nu-rw/');
    return r;
  }

  var results = [], shown = 0, PAGE = 15;
  function render() {
    var list = document.getElementById('csList'), html = '';
    results.slice(shown, shown + PAGE).forEach(function (r) {
      var d = r.doc;
      var labels = (d.l || []).slice(0, 3).map(function (l) { return '<span class="cs-label">' + esc(l) + '</span>'; }).join('');
      html += '<article class="cs-card"><a class="cs-thumb" href="' + esc(d.u) + '" tabindex="-1" aria-hidden="true">' +
        (d.i ? '<img alt="" decoding="async" height="85" loading="lazy" src="' + esc(thumb(d.i)) + '" width="120"/>' : '<span class="cs-noimg">&#128196;</span>') + '</a>' +
        '<div class="cs-body"><h2 class="cs-name"><a href="' + esc(d.u) + '">' + hl(d.t) + '</a></h2>' +
        '<p class="cs-snip">' + hl(d.s.slice(0, 170)) + (d.s.length > 170 ? '…' : '') + '</p>' +
        '<div class="cs-meta">' + labels + '<span class="cs-match">تطابق ' + r.m + ' من ' + qt.length + ' كلمات</span></div></div></article>';
    });
    list.insertAdjacentHTML('beforeend', html);
    shown += PAGE;
    var more = document.getElementById('csMore');
    if (more) more.parentNode.removeChild(more);
    if (shown < results.length) {
      list.insertAdjacentHTML('afterend', '<button class="cs-more" id="csMore" type="button">عرض المزيد (' + (results.length - shown) + ')</button>');
      document.getElementById('csMore').addEventListener('click', render);
    }
  }

  load().then(function (docs) {
    docs.forEach(function (d) {
      var tw = toks(d.t, true), lw = toks((d.l || []).join(' '), true), sw = toks(d.s, true), m = 0, sc = 0;
      qt.forEach(function (t) {
        var s = 0;
        if (hit(t, tw)) s += 5;
        if (hit(t, lw)) s += 4;
        if (hit(t, sw)) s += 1.5;
        if (s) { m++; sc += s; }
      });
      if (m) results.push({ doc: d, m: m, s: sc * (m === qt.length ? 1.5 : 1) });
    });
    results.sort(function (a, b) { return b.m - a.m || b.s - a.s || (a.doc.d < b.doc.d ? 1 : -1); });
    var cnt = document.getElementById('csCount');
    if (!results.length) {
      cnt.innerHTML = 'لم نجد مقالات مطابقة. جرّب كلمات أبسط، أو <a href="/search?q=' + encodeURIComponent(Q) + '&cs=0">شاهد النتائج الأصلية</a>.';
      return;
    }
    cnt.textContent = results.length + ' مقال مطابق';
    document.title = 'نتائج البحث: ' + Q;
    render();
  }).catch(fail);
})();
