body.script:
//
/* التوهج يبدأ بعد أول تفاعل + نبض الفوتر (مؤجل) */
(function(){


  function idle(f){ if('requestIdleCallback' in window) requestIdleCallback(f,{timeout:4000}); else setTimeout(f,2000); }

  function startGlow(){
    try{
      document.documentElement.classList.add('glow-on');
      if(!('IntersectionObserver' in window)) return;
      var cards=[].slice.call(document.querySelectorAll('.post-card22,.post-card'));
      if(!cards.length) return;
      var vis=new IntersectionObserver(function(es){
        es.forEach(function(e){e.target.classList.toggle('glow-paused',!e.isIntersecting)});
      },{rootMargin:'80px'});
      cards.forEach(function(c){vis.observe(c)});
    }catch(e){}
  }
  if(typeof window.onFirstInteraction==='function') window.onFirstInteraction(startGlow,30000);
  else window.addEventListener('load',function(){setTimeout(startGlow,8000)});

  idle(function(){
    try{
      var ecg=document.querySelector('.footer-ecg');
      if(ecg){
        if('IntersectionObserver' in window){
          new IntersectionObserver(function(es){es.forEach(function(e){ecg.classList.toggle('on',e.isIntersecting)})},{threshold:.3}).observe(ecg);
        }else ecg.classList.add('on');
      }
      var m=document.querySelector('meta[name="theme-color"]');
      if(m){
        var tc=function(){var v=getComputedStyle(document.body).getPropertyValue('--card-bg').trim(); if(v) m.setAttribute('content',v)};
        tc();
        new MutationObserver(tc).observe(document.body,{attributes:true,attributeFilter:['data-theme']});
      }
    }catch(e){}
  });
})();

/* ===== عرض صورة الكارت مكبّرة + تلوين كلمة من العنوان (بعد التحميل فقط) ===== */
(function(){
  var lb=null,prevFocus=null;
  function build(){
    lb=document.createElement('div');
    lb.className='img-lb';lb.setAttribute('role','dialog');lb.setAttribute('aria-modal','true');lb.setAttribute('aria-label','عرض الصورة');
    lb.innerHTML='<div class="img-lb-frame"><button type="button" class="img-lb-x" aria-label="إغلاق">&#10005;</button><img alt=""></div>';
    document.body.appendChild(lb);
    lb.addEventListener('click',function(e){if(e.target===lb||(e.target.closest&&e.target.closest('.img-lb-x')))close()});
  }
  function close(){
    if(!lb)return;lb.classList.remove('open');document.body.style.overflow='';
    if(prevFocus&&prevFocus.focus)prevFocus.focus();prevFocus=null;
  }
  function open(im){
    if(!lb)build();
    var small=im.currentSrc||im.src,big=small.replace(/\/(?:s|w)\d+(?:-[a-z0-9-]+)?\//i,'/s1600/');
    var view=lb.querySelector('img');view.alt=im.alt||'';view.src=small;
    if(big!==small){var pre=new Image();pre.onload=function(){if(lb.classList.contains('open'))view.src=big};pre.src=big}
    prevFocus=document.activeElement;lb.classList.add('open');document.body.style.overflow='hidden';
    lb.querySelector('.img-lb-x').focus();
  }
  document.addEventListener('click',function(e){
    var im=e.target.closest&&e.target.closest('.post-card22 .post-image22 img');
    if(!im||e.button||e.ctrlKey||e.metaKey||e.shiftKey)return;
    e.preventDefault();open(im);
  });
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&lb&&lb.classList.contains('open')){e.preventDefault();close()}});

  function accentTitles(){
    try{
      document.querySelectorAll('.post-card22 .post-title22 a').forEach(function(a){
        if(a.querySelector('.tw-m'))return;
        var txt=a.textContent.trim(),words=txt.split(/\s+/);
        var idx=[];words.forEach(function(w,i){if(w.replace(/[^\u0600-\u06FFa-zA-Z0-9]/g,'').length>=3)idx.push(i)});
        if(words.length<3||!idx.length)return;
        var h=0;for(var i=0;i<txt.length;i++)h=(h*31+txt.charCodeAt(i))>>>0;
        var pick=idx[h%idx.length];
        a.textContent='';
        words.forEach(function(w,i){
          if(i)a.appendChild(document.createTextNode(' '));
          if(i===pick){var s=document.createElement('span');s.className='tw-m';s.textContent=w;a.appendChild(s)}
          else a.appendChild(document.createTextNode(w));
        });
      });
    }catch(e){}
  }
  function later(){if('requestIdleCallback' in window)requestIdleCallback(accentTitles,{timeout:3000});else setTimeout(accentTitles,2500)}
  if(document.readyState==='complete')later();else window.addEventListener('load',later);
})();

/* ===== إحساس سرعة عند الانتقال: prefetch + شاشة تحميل (logo + blur) بعد أول تفاعل فقط ===== */
(function(){
  var LOGO='https://wsrv.nl/?url=raw.githubusercontent.com/momenelhamahmy158-creator/files/refs/heads/main/1000477703.jpg&w=240&h=240&fit=cover&output=webp&q=80';
  var done={},ov=null,timer=0;
  function pre(e){
    var a=e.target.closest&&e.target.closest('.post-card22 a[href]');
    if(!a||done[a.href]||a.origin!==location.origin)return;
    done[a.href]=1;var l=document.createElement('link');l.rel='prefetch';l.href=a.href;document.head.appendChild(l);
  }
  document.addEventListener('touchstart',pre,{passive:true});
  document.addEventListener('mouseover',pre,{passive:true});
  function build(){
    if(ov)return;
    ov=document.createElement('div');ov.className='nav-ld';ov.setAttribute('aria-hidden','true');
    ov.innerHTML='<div class="nav-ld-box"><div class="nav-ld-ring"></div><img alt="" width="68" height="68" decoding="async"></div>';
    document.body.appendChild(ov);ov.querySelector('img').src=LOGO;
  }
  function warm(){['touchstart','pointerdown','scroll','mousemove','keydown'].forEach(function(n){removeEventListener(n,warm)});
    (window.requestIdleCallback||setTimeout)(build)}
  ['touchstart','pointerdown','scroll','mousemove','keydown'].forEach(function(n){addEventListener(n,warm,{passive:true})});
  function show(){build();ov.classList.add('on');clearTimeout(timer);timer=setTimeout(hide,10000)}
  function hide(){if(ov)ov.classList.remove('on');clearTimeout(timer)}
  document.addEventListener('click',function(e){
    if(e.defaultPrevented||e.button||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;
    var a=e.target.closest&&e.target.closest('a[href]');if(!a)return;
    if(a.target&&a.target!=='_self')return;if(a.hasAttribute('download'))return;
    var h=a.getAttribute('href');if(!h||h.charAt(0)==='#'||/^(javascript|mailto|tel|sms|blob|data):/i.test(h))return;
    if(a.origin!==location.origin)return;
    if(a.pathname===location.pathname&&a.search===location.search&&a.hash)return;
    show();
  });
  window.addEventListener('pageshow',hide);
})();
/* تخفيف التمرير: إيقاف حركات الإطار مؤقتًا أثناء السكرول */
(function(){var st=0,r=document.documentElement;
addEventListener('scroll',function(){if(!st)r.classList.add('is-scrolling');clearTimeout(st);st=setTimeout(function(){r.classList.remove('is-scrolling');st=0},140)},{passive:true});})();
