/* زر "رد" على التعليقات: يعمل حتى لو مكتبة تعليقات بلوجر غير محمّلة */
(function(){
  var ed=null,orig=null,base='',hash='',cancel=null;
  function prep(){
    ed=document.getElementById('comment-editor');if(!ed)return false;
    if(!orig)orig=ed.parentNode;
    if(!base){
      var s=ed.getAttribute('src')||'';
      if(!s){var a=document.getElementById('comment-editor-src');s=a?a.href:''}
      var p=s.split('#');base=p[0];hash=p[1]||'';
    }
    return !!base;
  }
  function hideExtra(){
    document.querySelectorAll('#comments a.comment-reply').forEach(function(a){
      var c=a.closest('.comment-actions,.comment-replybox-thread,.comment-replybox-single');
      if(c&&!c.classList.contains('comment-actions'))a.style.display='none';
    });
  }
  hideExtra();document.addEventListener('DOMContentLoaded',hideExtra);addEventListener('load',hideExtra);
  function restore(){
    if(cancel){cancel.remove();cancel=null}
    if(ed&&orig&&ed.parentNode!==orig){orig.appendChild(ed);ed.src=base+(hash?'#'+hash:'')}
  }
  document.addEventListener('click',function(e){
    var a=e.target.closest&&e.target.closest('.comment-reply,.comment-replybox-single a');
    if(!a||!a.closest('#comments,#comment-holder'))return;
    var holder=a.closest('.comment');if(!holder)return;
    var id=a.getAttribute('data-comment-id')||(holder.id||'').replace(/^c/,'');
    if(!/^[0-9]+$/.test(id)||!prep())return;
    e.preventDefault();e.stopPropagation();
    restore();
    var box=document.getElementById('c'+id+'-ce')||holder.querySelector(':scope>.comment-replybox-single');
    if(!box){box=document.createElement('div');box.style.gridColumn='1 / -1';holder.appendChild(box)}
    cancel=document.createElement('button');cancel.type='button';cancel.textContent='إلغاء الرد';
    cancel.style.cssText='all:unset;cursor:pointer;display:block;margin:10px 0 6px;font-size:.8rem;font-weight:700;color:var(--primary)';
    cancel.onclick=restore;
    box.appendChild(cancel);box.appendChild(ed);
    ed.height='300';ed.style.display='block';
    ed.src=base+'&parentID='+encodeURIComponent(id)+(hash?'#'+hash:'');
    box.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
  },true);
})();
