(function(){
  var body=document.getElementById('postBody');if(!body)return;
  var pt=document.body.getAttribute('data-page-type');if(pt&&pt!=='item')return;
  var SDK='https://cdn.responsivevoice.org/sdk/latest/responsivevoice.js',KEY='Gys33C6G',VOICE='Arabic Male',CPS=14;
  var speeds=[1,1.25,1.5];
  var wrap,row,main,prevB,nextB,spdB,stopB,label,meter,elT,totT,track,fill;
  var parts=[],total=0,cur=-1,token=0,playing=false,paused=false,fixed=false,si=0,sdk=0,waiters=[],mk0=null,partMs=0,timer=0;
  function mk(tag,css,txt){var e=document.createElement(tag);if(css)e.style.cssText=css;if(txt)e.textContent=txt;if(tag==='button')e.type='button';return e}
  function bsz(){return innerWidth<400?30:34}
  function btnCss(primary){var s=bsz();return'all:unset;box-sizing:border-box;flex:none;width:'+s+'px;height:'+s+'px;display:inline-grid;place-items:center;border-radius:50%;cursor:pointer;font:700 14px/1 system-ui,sans-serif;-webkit-tap-highlight-color:transparent;'+(primary?'background:var(--primary);color:#fff':'color:var(--primary)')}
  function fmt(s){s=Math.max(0,Math.round(s));var m=Math.floor(s/60),r=s%60;return m+':'+(r<10?'0':'')+r}
  function calc(){var s=0;parts.forEach(function(p){p.start=s;p.dur=p.text.length/(CPS*speeds[si]);s+=p.dur});total=s}
  function collect(){
    var out=[],h1=document.querySelector('h1.post-title');
    if(h1){var t1=h1.textContent.replace(/\s+/g,' ').trim();if(t1.length>1)out.push({el:h1,text:t1})}
    body.querySelectorAll('h1,h2,h3,h4,h5,h6,p,li').forEach(function(el){
      var host=el.parentElement;
      if(host&&host.closest('faq,table,pre,code,figure,nav,button,form,[data-no-tts],.toc-widget,#tocList'))return;
      if(el.querySelector('p,li,h1,h2,h3,h4,h5,h6'))return;
      var tx=el.textContent.replace(/\s+/g,' ').trim(),isH=/^H[1-6]$/.test(el.tagName);
      if(tx.length<(isH?2:8)||!el.offsetParent)return;
      out.push({el:el,text:tx});
    });
    var AUTH=/(?:(?:الكاتب|بقلم)\s*[:：]?\s*)?د\.?\s*مؤمن\s*عبد\s*المنعم\.?/,found=false;
    out.forEach(function(p){if(AUTH.test(p.text)){found=true;p.text=p.text.replace(AUTH,'الكاتب: الدكتور مؤمن عبدالمنعم.');p.pause=1000}});
    if(!found)out.splice(h1&&out.length?1:0,0,{el:null,text:'الكاتب: الدكتور مؤمن عبدالمنعم.',pause:1000});
    parts=out;calc();
  }
  function idleLabel(){label.textContent='استمع إلى المقال · '+Math.max(1,Math.round(total/60))+' د'}
  function layout(){
    var common='direction:ltr;box-sizing:border-box;position:relative;overflow:hidden;border:1px solid var(--card-border);background:var(--card-bg);display:flex;';
    wrap.style.cssText=fixed
      ?common+'flex-direction:column;gap:6px;padding:8px 12px 10px;border-radius:18px;position:fixed;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));z-index:9500;width:max-content;max-width:55%;margin:0;box-shadow:0 10px 30px rgba(0,0,0,.22)'
      :common+'align-items:center;padding:6px 10px;border-radius:999px;width:100%;margin:0 0 18px;box-shadow:0 4px 14px rgba(0,0,0,.06)';
    row.style.cssText='display:flex;align-items:center;gap:6px;'+(fixed?'justify-content:center':'width:100%');
    [main,prevB,nextB,spdB,stopB].forEach(function(b,i){b.style.cssText=btnCss(i===0)});
    prevB.style.display=nextB.style.display=spdB.style.display=stopB.style.display=fixed?'inline-grid':'none';
    label.style.display=fixed?'none':'inline';
    meter.style.display=fixed?'flex':'none';
    main.textContent=(playing&&!paused)?'\u275A\u275A':'\u25B6';
    main.setAttribute('aria-label',(playing&&!paused)?'إيقاف مؤقت':'تشغيل');
    spdB.textContent=speeds[si]+'x';spdB.style.fontSize='11px';
  }
  function paint(){
    if(cur<0||!parts[cur]){fill.style.width='0';elT.textContent='0:00';totT.textContent=fmt(total);return}
    var now=parts[cur].start+Math.min(partMs/1000,parts[cur].dur),pc=total?Math.min(100,now/total*100):0;
    fill.style.width=pc+'%';elT.textContent=fmt(now);totT.textContent=fmt(total);track.setAttribute('aria-valuenow',String(Math.round(pc)));
  }
  function build(){
    if(wrap)return;collect();if(parts.length<2)return;
    wrap=mk('div','');wrap.setAttribute('role','group');wrap.setAttribute('aria-label','قارئ المقال الصوتي');
    row=mk('div','');
    main=mk('button','','\u25B6');prevB=mk('button','','\u23EE');nextB=mk('button','','\u23ED');spdB=mk('button','','1x');stopB=mk('button','','\u25A0');
    main.setAttribute('aria-label','تشغيل');prevB.setAttribute('aria-label','الفقرة السابقة');nextB.setAttribute('aria-label','الفقرة التالية');spdB.setAttribute('aria-label','سرعة القراءة');stopB.setAttribute('aria-label','إيقاف وإغلاق');
    label=mk('span','font-size:13px;font-weight:600;line-height:1.2;font-family:inherit;color:var(--text-muted);flex:1;text-align:right;padding:0 4px 0 8px;direction:rtl;white-space:nowrap');
    row.appendChild(prevB);row.appendChild(main);row.appendChild(nextB);row.appendChild(spdB);row.appendChild(stopB);row.appendChild(label);
    meter=mk('div','align-items:center;gap:8px;font:600 11px/1 system-ui,sans-serif;color:var(--text-muted);font-variant-numeric:tabular-nums');
    elT=mk('span','flex:none;min-width:30px;text-align:left','0:00');totT=mk('span','flex:none;min-width:30px;text-align:right','0:00');
    track=mk('div','position:relative;flex:1;min-width:40px;height:8px;border-radius:8px;background:rgba(100,116,139,.25);background:color-mix(in srgb,var(--primary) 20%,transparent);cursor:pointer;overflow:hidden');
    track.setAttribute('role','progressbar');track.setAttribute('aria-label','تقدّم القراءة');track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax','100');track.setAttribute('aria-valuenow','0');
    fill=mk('div','height:100%;width:0;border-radius:8px;background:var(--primary);transition:width .25s linear');
    track.appendChild(fill);meter.appendChild(elT);meter.appendChild(track);meter.appendChild(totT);
    wrap.appendChild(row);wrap.appendChild(meter);
    idleLabel();layout();paint();body.parentNode.insertBefore(wrap,body);
    main.onclick=onMain;prevB.onclick=function(){go(cur-1)};nextB.onclick=function(){go(cur+1)};
