  function go(i){if(!playing)return;paused=false;speakAt(Math.max(0,i))}
  function split(txt){
    var m=txt.match(/[^.!?؟؛:…،]+[.!?؟؛:…،]*/g)||[txt],out=[],buf='';
    function flush(){if(buf.trim())out.push(buf.trim());buf=''}
    m.forEach(function(s){
      s=s.trim();if(!s)return;
      while(s.length>150){var k=s.lastIndexOf(' ',140);if(k<40)k=140;flush();out.push(s.slice(0,k).trim());s=s.slice(k).trim()}
      if(buf&&buf.length+s.length>110)flush();
      buf=buf?buf+' '+s:s;
      if(buf.length>=60)flush();
    });
    flush();
    return out.length?out:[txt];
  }
  function speakAt(i){
    if(i>=parts.length){stop();return}
    var my=++token,list=split(parts[i].text),k=0;
    cur=i;partMs=0;mark(i);playing=true;paused=false;layout();paint();
    if(!timer)timer=setInterval(function(){if(playing&&!paused&&cur>=0){partMs+=250;paint()}},250);
