  }
  function mark(i){
    unmark();var el=parts[i].el;if(!el)return;var cs=getComputedStyle(el);
    function px(k){return parseFloat(cs[k])||0}
    var PV=6,PH=12,BD=2;
    mk0={el:el,s:el.getAttribute('style')};
    el.style.transition='background-color .25s ease';
    el.style.padding=(px('paddingTop')+PV)+'px '+(px('paddingRight')+PH)+'px '+(px('paddingBottom')+PV)+'px '+(px('paddingLeft')+PH)+'px';
    el.style.margin=(px('marginTop')-PV)+'px '+(px('marginRight')-PH)+'px '+(px('marginBottom')-PV-BD)+'px '+(px('marginLeft')-PH)+'px';
